-- Упражнения книги 19, глава 28 (Администрирование Linux). Файл строит автор-скрипт (не в репозитории); после правок можно редактировать и вручную.

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 28, 'la28-api-version', 0, 'c', 'Версия API KVM', 'Это упражнение из дорожной карты: крошечная программа, которая открывает /dev/kvm и спрашивает версию API. Напишите int kvm_api_version(void): откройте /dev/kvm с флагами O_RDWR | O_CLOEXEC, вызовите ioctl(fd, KVM_GET_API_VERSION, 0), закройте дескриптор и верните версию. Если open или ioctl не удался, верните -errno (отрицательный номер ошибки; errno надо запомнить до close, потому что close может его перезаписать). Дескриптор не должен утекать ни на одном пути. Устройства /dev/kvm в песочнице нет: драйвер подставляет МОДЕЛЬ ядра (лабораторное упрощение, константы и структуры настоящие, из linux/kvm.h; поведение модели описано в условии). Пишите обычный код с open, ioctl, close, mmap, как для настоящего устройства.', '#include <errno.h>
#include <fcntl.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/kvm.h>

int kvm_api_version(void) {
    // открыть /dev/kvm, спросить версию, закрыть
    return -1;
}
', 'Версия — это возвращаемое значение ioctl, а не данные через указатель. Для настоящего ядра её значение 12.', '{"driver": "/*__DRIVER__*/\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <stdint.h>\n#include <stdarg.h>\n#include <errno.h>\n#include <fcntl.h>\n#include <unistd.h>\n#include <sys/mman.h>\n#include <sys/ioctl.h>\n#include <linux/kvm.h>\n\n/* ---- LAB MODEL of /dev/kvm: a fake kernel behind the linker''s --wrap (the sandbox has no /dev/kvm) ---- */\nextern int __real_open(const char *, int, ...);\nextern int __real_close(int);\nextern void *__real_mmap(void *, size_t, int, int, int, off_t);\nextern int __real_munmap(void *, size_t);\n\n#define PG 4096UL\n#define M_FDS 16\n#define M_SLOTS 32\n#define M_MAXV 8\nenum { K_FREE, K_SYS, K_VM, K_VCPU };\nstruct m_slot { int used; uint64_t gpa, size, uaddr; };\nstruct m_vm { struct m_slot s[M_SLOTS]; int nv; int ids[M_MAXV]; };\nstruct m_fd { int kind, vm, id; struct kvm_run *run; size_t runlen; uint64_t pc; uint8_t acc; int pend; };\nstatic struct m_fd m_fds[M_FDS];\nstatic struct m_vm m_vms[4];\nstatic int m_nvm;\nstatic struct { void *a; size_t l; } m_maps[32];\nstatic int m_open_err, m_api = 12, m_vm_err, m_runs, m_opens, m_oflags;\nstatic unsigned m_eintr; /* bit k set: the (k+1)-th KVM_RUN fails with EINTR */\n\nstatic int m_fail(int e) { errno = e; return -1; }\nstatic struct m_fd *m_get(int fd) {\n    int i = fd - 100;\n    return (i < 0 || i >= M_FDS || m_fds[i].kind == K_FREE) ? NULL : &m_fds[i];\n}\nstatic int m_alloc(int kind, int vm, int id) {\n    for (int i = 0; i < M_FDS; i++)\n        if (m_fds[i].kind == K_FREE) {\n            memset(&m_fds[i], 0, sizeof m_fds[i]);\n            m_fds[i].kind = kind; m_fds[i].vm = vm; m_fds[i].id = id;\n            return 100 + i;\n        }\n    return -1;\n}\nstatic int m_nopen(void) { int n = 0; for (int i = 0; i < M_FDS; i++) n += m_fds[i].kind != K_FREE; return n; }\nstatic int m_nmaps(void) { int n = 0; for (int i = 0; i < 32; i++) n += m_maps[i].a != NULL; return n; }\nstatic long m_cap(unsigned long c) {\n    switch (c) {\n    case KVM_CAP_USER_MEMORY: case KVM_CAP_IMMEDIATE_EXIT: case KVM_CAP_MP_STATE:\n    case KVM_CAP_IOEVENTFD: case KVM_CAP_IRQFD: return 1;\n    case KVM_CAP_NR_VCPUS: return 4;\n    case KVM_CAP_MAX_VCPUS: return M_MAXV;\n    case KVM_CAP_NR_MEMSLOTS: return M_SLOTS;\n    default: return 0;\n    }\n}\nstatic int m_gread(struct m_vm *v, uint64_t gpa, uint8_t *out, int n) {\n    for (int k = 0; k < n; k++) {\n        int ok = 0;\n        for (int i = 0; i < M_SLOTS && !ok; i++) {\n            struct m_slot *s = &v->s[i];\n            if (s->used && gpa + k >= s->gpa && gpa + k < s->gpa + s->size) {\n                out[k] = ((uint8_t *)(uintptr_t)s->uaddr)[gpa + k - s->gpa];\n                ok = 1;\n            }\n        }\n        if (!ok) return -1;\n    }\n    return 0;\n}\n/* the toy guest: opcode lengths; this is NOT machine code, it is the lab''s own tiny instruction set */\nstatic int m_oplen(int op) {\n    switch (op) {\n    case 0x00: case 0xFF: return 1;\n    case 0x01: return 4;  /* OUT port,imm8 */\n    case 0x02: return 3;  /* IN port -> acc */\n    case 0x03: return 6;  /* MMIO write addr32,imm8 */\n    case 0x04: return 5;  /* MMIO read addr32 -> acc */\n    case 0x05: return 3;  /* OUT port,acc */\n    case 0x06: return 2;  /* acc += imm8 */\n    default: return 0;\n    }\n}\nstatic int m_run(struct m_fd *f) {\n    struct m_vm *v = &m_vms[f->vm];\n    struct kvm_run *r = f->run;\n    if (!r) return m_fail(EINVAL);\n    uint8_t *pio = (uint8_t *)r + PG;\n    m_runs++;\n    if ((m_runs <= 31 && ((m_eintr >> (m_runs - 1)) & 1)) || r->immediate_exit) {\n        r->exit_reason = KVM_EXIT_INTR;\n        return m_fail(EINTR);\n    }\n    if (f->pend == 1) f->acc = pio[0];\n    if (f->pend == 2) f->acc = r->mmio.data[0];\n    f->pend = 0;\n    for (;;) {\n        uint8_t b[8];\n        int n;\n        if (m_gread(v, f->pc, b, 1)) { r->exit_reason = KVM_EXIT_FAIL_ENTRY; r->fail_entry.hardware_entry_failure_reason = 0x1000; r->fail_entry.cpu = 0; return 0; }\n        n = m_oplen(b[0]);\n        if (n == 0) {\n            r->exit_reason = KVM_EXIT_INTERNAL_ERROR;\n            r->internal.suberror = KVM_INTERNAL_ERROR_EMULATION;\n            r->internal.ndata = 0;\n            return 0;\n        }\n        if (m_gread(v, f->pc, b, n)) { r->exit_reason = KVM_EXIT_FAIL_ENTRY; r->fail_entry.hardware_entry_failure_reason = 0x1000; r->fail_entry.cpu = 0; return 0; }\n        f->pc += n;\n        switch (b[0]) {\n        case 0x00: r->exit_reason = KVM_EXIT_HLT; return 0;\n        case 0xFF: r->exit_reason = KVM_EXIT_SHUTDOWN; return 0;\n        case 0x06: f->acc = (uint8_t)(f->acc + b[1]); break;\n        case 0x01: case 0x05:\n            if (f->runlen < 2 * PG) return m_fail(EFAULT);\n            r->exit_reason = KVM_EXIT_IO;\n            r->io.direction = KVM_EXIT_IO_OUT; r->io.size = 1; r->io.count = 1;\n            r->io.port = (uint16_t)(b[1] | b[2] << 8); r->io.data_offset = PG;\n            pio[0] = b[0] == 0x01 ? b[3] : f->acc;\n            return 0;\n        case 0x02:\n            if (f->runlen < 2 * PG) return m_fail(EFAULT);\n            r->exit_reason = KVM_EXIT_IO;\n            r->io.direction = KVM_EXIT_IO_IN; r->io.size = 1; r->io.count = 1;\n            r->io.port = (uint16_t)(b[1] | b[2] << 8); r->io.data_offset = PG;\n            pio[0] = 0; f->pend = 1;\n            return 0;\n        case 0x03: case 0x04:\n            r->exit_reason = KVM_EXIT_MMIO;\n            r->mmio.phys_addr = (uint32_t)b[1] | (uint32_t)b[2] << 8 | (uint32_t)b[3] << 16 | (uint32_t)b[4] << 24;\n            memset(r->mmio.data, 0, 8);\n            r->mmio.len = 1;\n            if (b[0] == 0x03) { r->mmio.is_write = 1; r->mmio.data[0] = b[5]; }\n            else { r->mmio.is_write = 0; f->pend = 2; }\n            return 0;\n        }\n    }\n}\nstatic int m_set_region(struct m_fd *f, struct kvm_userspace_memory_region *m) {\n    struct m_vm *v = &m_vms[f->vm];\n    unsigned slot = m->slot & 0xffff;\n    if (m->flags & ~(KVM_MEM_LOG_DIRTY_PAGES | KVM_MEM_READONLY)) return m_fail(EINVAL);\n    if ((m->memory_size & (PG - 1)) || (m->guest_phys_addr & (PG - 1)) || (m->userspace_addr & (PG - 1))) return m_fail(EINVAL);\n    if ((m->slot >> 16) != 0 || slot >= M_SLOTS) return m_fail(EINVAL);\n    if (m->guest_phys_addr + m->memory_size < m->guest_phys_addr) return m_fail(EINVAL);\n    struct m_slot *s = &v->s[slot];\n    if (m->memory_size == 0) {\n        if (!s->used) return m_fail(EINVAL);\n        s->used = 0;\n        return 0;\n    }\n    if (s->used && (m->userspace_addr != s->uaddr || m->memory_size != s->size)) return m_fail(EINVAL);\n    for (int i = 0; i < M_SLOTS; i++)\n        if (i != (int)slot && v->s[i].used && m->guest_phys_addr < v->s[i].gpa + v->s[i].size &&\n            v->s[i].gpa < m->guest_phys_addr + m->memory_size)\n            return m_fail(EEXIST);\n    s->used = 1; s->gpa = m->guest_phys_addr; s->size = m->memory_size; s->uaddr = m->userspace_addr;\n    return 0;\n}\nint __wrap_open(const char *path, int flags, ...) {\n    if (strcmp(path, \"/dev/kvm\") == 0) {\n        m_opens++; m_oflags = flags;\n        if (m_open_err) return m_fail(m_open_err);\n        int fd = m_alloc(K_SYS, 0, 0);\n        return fd < 0 ? m_fail(EMFILE) : fd;\n    }\n    va_list ap; va_start(ap, flags);\n    int mode = (flags & O_CREAT) ? va_arg(ap, int) : 0;\n    va_end(ap);\n    return __real_open(path, flags, mode);\n}\nint __wrap_close(int fd) {\n    struct m_fd *f = m_get(fd);\n    if (!f) return __real_close(fd);\n    f->kind = K_FREE;\n    return 0;\n}\nint __wrap_ioctl(int fd, unsigned long req, ...) {\n    va_list ap; va_start(ap, req);\n    unsigned long arg = va_arg(ap, unsigned long);\n    va_end(ap);\n    struct m_fd *f = m_get(fd);\n    if (!f) return m_fail(EBADF);\n    if (f->kind == K_SYS) {\n        if (req == KVM_GET_API_VERSION) return (unsigned)arg ? m_fail(EINVAL) : m_api;\n        if (req == KVM_CHECK_EXTENSION) return (int)m_cap((unsigned)arg);\n        if (req == KVM_GET_VCPU_MMAP_SIZE) return (unsigned)arg ? m_fail(EINVAL) : (int)(3 * PG);\n        if (req == KVM_CREATE_VM) {\n            if (m_vm_err) return m_fail(m_vm_err);\n            if ((unsigned)arg != 0 || m_nvm >= 4) return m_fail(EINVAL);\n            int nfd = m_alloc(K_VM, m_nvm, 0);\n            if (nfd < 0) return m_fail(EMFILE);\n            m_nvm++;\n            return nfd;\n        }\n    } else if (f->kind == K_VM) {\n        struct m_vm *v = &m_vms[f->vm];\n        if (req == KVM_CHECK_EXTENSION) return (int)m_cap((unsigned)arg);\n        if (req == KVM_CREATE_VCPU) {\n            if (v->nv >= M_MAXV) return m_fail(EINVAL);\n            for (int i = 0; i < v->nv; i++) if (v->ids[i] == (int)(unsigned)arg) return m_fail(EEXIST);\n            int nfd = m_alloc(K_VCPU, f->vm, (int)(unsigned)arg);\n            if (nfd < 0) return m_fail(EMFILE);\n            v->ids[v->nv++] = (int)(unsigned)arg;\n            return nfd;\n        }\n        if (req == KVM_SET_USER_MEMORY_REGION) {\n            if (arg == 0) return m_fail(EFAULT);\n            return m_set_region(f, (struct kvm_userspace_memory_region *)arg);\n        }\n    } else if (f->kind == K_VCPU) {\n        if (req == KVM_RUN) return (unsigned)arg ? m_fail(EINVAL) : m_run(f);\n    }\n    return m_fail(ENOTTY);\n}\nvoid *__wrap_mmap(void *addr, size_t len, int prot, int flags, int fd, off_t off) {\n    struct m_fd *f = (flags & MAP_ANONYMOUS) ? NULL : m_get(fd);\n    if (f && f->kind != K_VCPU) { errno = ENODEV; return MAP_FAILED; }\n    if (f && (off != 0 || len == 0 || len > 3 * PG)) { errno = EINVAL; return MAP_FAILED; }\n    if (!f && (flags & MAP_ANONYMOUS) == 0) return __real_mmap(addr, len, prot, flags, fd, off);\n    void *p = __real_mmap(f ? NULL : addr, f ? 3 * PG : len, f ? PROT_READ | PROT_WRITE : prot,\n                          f ? MAP_SHARED | MAP_ANONYMOUS : flags, f ? -1 : fd, f ? 0 : off);\n    if (p == MAP_FAILED) return p;\n    for (int i = 0; i < 32; i++)\n        if (!m_maps[i].a) { m_maps[i].a = p; m_maps[i].l = len; break; }\n    if (f) { f->run = p; f->runlen = len; }\n    return p;\n}\nint __wrap_munmap(void *addr, size_t len) {\n    int r = __real_munmap(addr, len);\n    if (r == 0)\n        for (int i = 0; i < 32; i++)\n            if (m_maps[i].a == addr) {\n                m_maps[i].a = NULL;\n                for (int k = 0; k < M_FDS; k++) if (m_fds[k].run == addr) m_fds[k].run = NULL;\n                break;\n            }\n    return r;\n}\n\n/* ---- helpers of the driver ---- */\nstatic void m_reset(void) {\n    memset(m_fds, 0, sizeof m_fds); memset(m_vms, 0, sizeof m_vms); memset(m_maps, 0, sizeof m_maps);\n    m_nvm = 0; m_open_err = 0; m_api = 12; m_vm_err = 0; m_runs = 0; m_opens = 0; m_oflags = 0; m_eintr = 0;\n}\nstatic const char *m_en(int e) {\n    switch (e) {\n    case ENOENT: return \"ENOENT\"; case EACCES: return \"EACCES\"; case EINVAL: return \"EINVAL\";\n    case EEXIST: return \"EEXIST\"; case EBADF: return \"EBADF\"; case EINTR: return \"EINTR\";\n    case EMFILE: return \"EMFILE\"; case ENOMEM: return \"ENOMEM\"; case EPROTO: return \"EPROTO\";\n    case E2BIG: return \"E2BIG\"; case EIO: return \"EIO\"; case ENOTTY: return \"ENOTTY\";\n    case EFAULT: return \"EFAULT\"; case ENODEV: return \"ENODEV\"; case EPERM: return \"EPERM\";\n    }\n    return \"E?\";\n}\nstatic void m_pr(const char *label, long r) {\n    if (r < 0 && r > -4096) printf(\"%s: -%s\\n\", label, m_en((int)-r));\n    else printf(\"%s: %ld\\n\", label, r);\n}\n/* print the result of a raw ioctl/mmap-like call that reports errors through errno */\nstatic void m_pre(const char *label, long r) {\n    int e = errno;\n    if (r < 0) printf(\"%s: -%s\\n\", label, m_en(e));\n    else printf(\"%s: %ld\\n\", label, r);\n}\nstatic void m_leaks(void) { printf(\"leaks: fds=%d maps=%d\\n\", m_nopen(), m_nmaps()); }\nstatic const char *m_kind(int fd) {\n    struct m_fd *f = m_get(fd);\n    return !f ? \"none\" : f->kind == K_SYS ? \"system\" : f->kind == K_VM ? \"vm\" : \"vcpu\";\n}\n/* driver-side setup of a VM with the guest program at guest address 0 and one vCPU mapped for KVM_RUN */\nstatic uint8_t *m_boot(const uint8_t *prog, int len, int *vcpu, struct kvm_run **run) {\n    int kvm = open(\"/dev/kvm\", O_RDWR | O_CLOEXEC);\n    int vm = ioctl(kvm, KVM_CREATE_VM, 0);\n    uint8_t *mem = mmap(NULL, PG, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);\n    memcpy(mem, prog, len);\n    struct kvm_userspace_memory_region r = { .slot = 0, .guest_phys_addr = 0, .memory_size = PG, .userspace_addr = (uintptr_t)mem };\n    ioctl(vm, KVM_SET_USER_MEMORY_REGION, &r);\n    *vcpu = ioctl(vm, KVM_CREATE_VCPU, 0);\n    *run = mmap(NULL, 3 * PG, PROT_READ | PROT_WRITE, MAP_SHARED, *vcpu, 0);\n    return mem;\n}\n\n\nint main(void) {\n    m_reset();\n    m_pr(\"normal\", kvm_api_version());\n    printf(\"flags: rdwr=%d cloexec=%d\\n\", (m_oflags & O_ACCMODE) == O_RDWR, (m_oflags & O_CLOEXEC) != 0);\n    m_leaks();\n    m_reset(); m_open_err = ENOENT;\n    m_pr(\"module not loaded\", kvm_api_version());\n    m_leaks();\n    m_reset(); m_open_err = EACCES;\n    m_pr(\"not in the kvm group\", kvm_api_version());\n    m_reset(); m_api = 11;\n    m_pr(\"old kernel\", kvm_api_version());\n    m_leaks();\n    return 0;\n}\n", "expected": ["normal: 12", "flags: rdwr=1 cloexec=1", "leaks: fds=0 maps=0", "module not loaded: -ENOENT", "leaks: fds=0 maps=0", "not in the kvm group: -EACCES", "old kernel: 11", "leaks: fds=0 maps=0"], "flags": "-std=gnu11 -O1 -Wall -Wl,--wrap=open,--wrap=ioctl,--wrap=close,--wrap=mmap,--wrap=munmap"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 28, 'la28-open-checked', 1, 'c', 'Открыть /dev/kvm с проверкой версии', 'Программа, которая работает с KVM, обязана отказаться, если версия API не равна KVM_API_VERSION (12). Напишите int kvm_open(void): откройте /dev/kvm (O_RDWR | O_CLOEXEC), проверьте версию и верните открытый дескриптор. Если open не удался, верните -errno. Если ioctl не удался, верните -errno этого вызова. Если версия не 12, верните -EPROTO. На любой ошибке дескриптор должен быть закрыт. Устройства /dev/kvm в песочнице нет: драйвер подставляет МОДЕЛЬ ядра (лабораторное упрощение, константы и структуры настоящие, из linux/kvm.h; поведение модели описано в условии). Пишите обычный код с open, ioctl, close, mmap, как для настоящего устройства.', '#include <errno.h>
#include <fcntl.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/kvm.h>

int kvm_open(void) {
    // open, проверка версии, при ошибке close и -errno / -EPROTO
    return -1;
}
', 'Сравнивайте с константой KVM_API_VERSION из заголовка, не с числом в коде. Закрывайте дескриптор до return, но после того, как сохранили errno.', '{"driver": "/*__DRIVER__*/\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <stdint.h>\n#include <stdarg.h>\n#include <errno.h>\n#include <fcntl.h>\n#include <unistd.h>\n#include <sys/mman.h>\n#include <sys/ioctl.h>\n#include <linux/kvm.h>\n\n/* ---- LAB MODEL of /dev/kvm: a fake kernel behind the linker''s --wrap (the sandbox has no /dev/kvm) ---- */\nextern int __real_open(const char *, int, ...);\nextern int __real_close(int);\nextern void *__real_mmap(void *, size_t, int, int, int, off_t);\nextern int __real_munmap(void *, size_t);\n\n#define PG 4096UL\n#define M_FDS 16\n#define M_SLOTS 32\n#define M_MAXV 8\nenum { K_FREE, K_SYS, K_VM, K_VCPU };\nstruct m_slot { int used; uint64_t gpa, size, uaddr; };\nstruct m_vm { struct m_slot s[M_SLOTS]; int nv; int ids[M_MAXV]; };\nstruct m_fd { int kind, vm, id; struct kvm_run *run; size_t runlen; uint64_t pc; uint8_t acc; int pend; };\nstatic struct m_fd m_fds[M_FDS];\nstatic struct m_vm m_vms[4];\nstatic int m_nvm;\nstatic struct { void *a; size_t l; } m_maps[32];\nstatic int m_open_err, m_api = 12, m_vm_err, m_runs, m_opens, m_oflags;\nstatic unsigned m_eintr; /* bit k set: the (k+1)-th KVM_RUN fails with EINTR */\n\nstatic int m_fail(int e) { errno = e; return -1; }\nstatic struct m_fd *m_get(int fd) {\n    int i = fd - 100;\n    return (i < 0 || i >= M_FDS || m_fds[i].kind == K_FREE) ? NULL : &m_fds[i];\n}\nstatic int m_alloc(int kind, int vm, int id) {\n    for (int i = 0; i < M_FDS; i++)\n        if (m_fds[i].kind == K_FREE) {\n            memset(&m_fds[i], 0, sizeof m_fds[i]);\n            m_fds[i].kind = kind; m_fds[i].vm = vm; m_fds[i].id = id;\n            return 100 + i;\n        }\n    return -1;\n}\nstatic int m_nopen(void) { int n = 0; for (int i = 0; i < M_FDS; i++) n += m_fds[i].kind != K_FREE; return n; }\nstatic int m_nmaps(void) { int n = 0; for (int i = 0; i < 32; i++) n += m_maps[i].a != NULL; return n; }\nstatic long m_cap(unsigned long c) {\n    switch (c) {\n    case KVM_CAP_USER_MEMORY: case KVM_CAP_IMMEDIATE_EXIT: case KVM_CAP_MP_STATE:\n    case KVM_CAP_IOEVENTFD: case KVM_CAP_IRQFD: return 1;\n    case KVM_CAP_NR_VCPUS: return 4;\n    case KVM_CAP_MAX_VCPUS: return M_MAXV;\n    case KVM_CAP_NR_MEMSLOTS: return M_SLOTS;\n    default: return 0;\n    }\n}\nstatic int m_gread(struct m_vm *v, uint64_t gpa, uint8_t *out, int n) {\n    for (int k = 0; k < n; k++) {\n        int ok = 0;\n        for (int i = 0; i < M_SLOTS && !ok; i++) {\n            struct m_slot *s = &v->s[i];\n            if (s->used && gpa + k >= s->gpa && gpa + k < s->gpa + s->size) {\n                out[k] = ((uint8_t *)(uintptr_t)s->uaddr)[gpa + k - s->gpa];\n                ok = 1;\n            }\n        }\n        if (!ok) return -1;\n    }\n    return 0;\n}\n/* the toy guest: opcode lengths; this is NOT machine code, it is the lab''s own tiny instruction set */\nstatic int m_oplen(int op) {\n    switch (op) {\n    case 0x00: case 0xFF: return 1;\n    case 0x01: return 4;  /* OUT port,imm8 */\n    case 0x02: return 3;  /* IN port -> acc */\n    case 0x03: return 6;  /* MMIO write addr32,imm8 */\n    case 0x04: return 5;  /* MMIO read addr32 -> acc */\n    case 0x05: return 3;  /* OUT port,acc */\n    case 0x06: return 2;  /* acc += imm8 */\n    default: return 0;\n    }\n}\nstatic int m_run(struct m_fd *f) {\n    struct m_vm *v = &m_vms[f->vm];\n    struct kvm_run *r = f->run;\n    if (!r) return m_fail(EINVAL);\n    uint8_t *pio = (uint8_t *)r + PG;\n    m_runs++;\n    if ((m_runs <= 31 && ((m_eintr >> (m_runs - 1)) & 1)) || r->immediate_exit) {\n        r->exit_reason = KVM_EXIT_INTR;\n        return m_fail(EINTR);\n    }\n    if (f->pend == 1) f->acc = pio[0];\n    if (f->pend == 2) f->acc = r->mmio.data[0];\n    f->pend = 0;\n    for (;;) {\n        uint8_t b[8];\n        int n;\n        if (m_gread(v, f->pc, b, 1)) { r->exit_reason = KVM_EXIT_FAIL_ENTRY; r->fail_entry.hardware_entry_failure_reason = 0x1000; r->fail_entry.cpu = 0; return 0; }\n        n = m_oplen(b[0]);\n        if (n == 0) {\n            r->exit_reason = KVM_EXIT_INTERNAL_ERROR;\n            r->internal.suberror = KVM_INTERNAL_ERROR_EMULATION;\n            r->internal.ndata = 0;\n            return 0;\n        }\n        if (m_gread(v, f->pc, b, n)) { r->exit_reason = KVM_EXIT_FAIL_ENTRY; r->fail_entry.hardware_entry_failure_reason = 0x1000; r->fail_entry.cpu = 0; return 0; }\n        f->pc += n;\n        switch (b[0]) {\n        case 0x00: r->exit_reason = KVM_EXIT_HLT; return 0;\n        case 0xFF: r->exit_reason = KVM_EXIT_SHUTDOWN; return 0;\n        case 0x06: f->acc = (uint8_t)(f->acc + b[1]); break;\n        case 0x01: case 0x05:\n            if (f->runlen < 2 * PG) return m_fail(EFAULT);\n            r->exit_reason = KVM_EXIT_IO;\n            r->io.direction = KVM_EXIT_IO_OUT; r->io.size = 1; r->io.count = 1;\n            r->io.port = (uint16_t)(b[1] | b[2] << 8); r->io.data_offset = PG;\n            pio[0] = b[0] == 0x01 ? b[3] : f->acc;\n            return 0;\n        case 0x02:\n            if (f->runlen < 2 * PG) return m_fail(EFAULT);\n            r->exit_reason = KVM_EXIT_IO;\n            r->io.direction = KVM_EXIT_IO_IN; r->io.size = 1; r->io.count = 1;\n            r->io.port = (uint16_t)(b[1] | b[2] << 8); r->io.data_offset = PG;\n            pio[0] = 0; f->pend = 1;\n            return 0;\n        case 0x03: case 0x04:\n            r->exit_reason = KVM_EXIT_MMIO;\n            r->mmio.phys_addr = (uint32_t)b[1] | (uint32_t)b[2] << 8 | (uint32_t)b[3] << 16 | (uint32_t)b[4] << 24;\n            memset(r->mmio.data, 0, 8);\n            r->mmio.len = 1;\n            if (b[0] == 0x03) { r->mmio.is_write = 1; r->mmio.data[0] = b[5]; }\n            else { r->mmio.is_write = 0; f->pend = 2; }\n            return 0;\n        }\n    }\n}\nstatic int m_set_region(struct m_fd *f, struct kvm_userspace_memory_region *m) {\n    struct m_vm *v = &m_vms[f->vm];\n    unsigned slot = m->slot & 0xffff;\n    if (m->flags & ~(KVM_MEM_LOG_DIRTY_PAGES | KVM_MEM_READONLY)) return m_fail(EINVAL);\n    if ((m->memory_size & (PG - 1)) || (m->guest_phys_addr & (PG - 1)) || (m->userspace_addr & (PG - 1))) return m_fail(EINVAL);\n    if ((m->slot >> 16) != 0 || slot >= M_SLOTS) return m_fail(EINVAL);\n    if (m->guest_phys_addr + m->memory_size < m->guest_phys_addr) return m_fail(EINVAL);\n    struct m_slot *s = &v->s[slot];\n    if (m->memory_size == 0) {\n        if (!s->used) return m_fail(EINVAL);\n        s->used = 0;\n        return 0;\n    }\n    if (s->used && (m->userspace_addr != s->uaddr || m->memory_size != s->size)) return m_fail(EINVAL);\n    for (int i = 0; i < M_SLOTS; i++)\n        if (i != (int)slot && v->s[i].used && m->guest_phys_addr < v->s[i].gpa + v->s[i].size &&\n            v->s[i].gpa < m->guest_phys_addr + m->memory_size)\n            return m_fail(EEXIST);\n    s->used = 1; s->gpa = m->guest_phys_addr; s->size = m->memory_size; s->uaddr = m->userspace_addr;\n    return 0;\n}\nint __wrap_open(const char *path, int flags, ...) {\n    if (strcmp(path, \"/dev/kvm\") == 0) {\n        m_opens++; m_oflags = flags;\n        if (m_open_err) return m_fail(m_open_err);\n        int fd = m_alloc(K_SYS, 0, 0);\n        return fd < 0 ? m_fail(EMFILE) : fd;\n    }\n    va_list ap; va_start(ap, flags);\n    int mode = (flags & O_CREAT) ? va_arg(ap, int) : 0;\n    va_end(ap);\n    return __real_open(path, flags, mode);\n}\nint __wrap_close(int fd) {\n    struct m_fd *f = m_get(fd);\n    if (!f) return __real_close(fd);\n    f->kind = K_FREE;\n    return 0;\n}\nint __wrap_ioctl(int fd, unsigned long req, ...) {\n    va_list ap; va_start(ap, req);\n    unsigned long arg = va_arg(ap, unsigned long);\n    va_end(ap);\n    struct m_fd *f = m_get(fd);\n    if (!f) return m_fail(EBADF);\n    if (f->kind == K_SYS) {\n        if (req == KVM_GET_API_VERSION) return (unsigned)arg ? m_fail(EINVAL) : m_api;\n        if (req == KVM_CHECK_EXTENSION) return (int)m_cap((unsigned)arg);\n        if (req == KVM_GET_VCPU_MMAP_SIZE) return (unsigned)arg ? m_fail(EINVAL) : (int)(3 * PG);\n        if (req == KVM_CREATE_VM) {\n            if (m_vm_err) return m_fail(m_vm_err);\n            if ((unsigned)arg != 0 || m_nvm >= 4) return m_fail(EINVAL);\n            int nfd = m_alloc(K_VM, m_nvm, 0);\n            if (nfd < 0) return m_fail(EMFILE);\n            m_nvm++;\n            return nfd;\n        }\n    } else if (f->kind == K_VM) {\n        struct m_vm *v = &m_vms[f->vm];\n        if (req == KVM_CHECK_EXTENSION) return (int)m_cap((unsigned)arg);\n        if (req == KVM_CREATE_VCPU) {\n            if (v->nv >= M_MAXV) return m_fail(EINVAL);\n            for (int i = 0; i < v->nv; i++) if (v->ids[i] == (int)(unsigned)arg) return m_fail(EEXIST);\n            int nfd = m_alloc(K_VCPU, f->vm, (int)(unsigned)arg);\n            if (nfd < 0) return m_fail(EMFILE);\n            v->ids[v->nv++] = (int)(unsigned)arg;\n            return nfd;\n        }\n        if (req == KVM_SET_USER_MEMORY_REGION) {\n            if (arg == 0) return m_fail(EFAULT);\n            return m_set_region(f, (struct kvm_userspace_memory_region *)arg);\n        }\n    } else if (f->kind == K_VCPU) {\n        if (req == KVM_RUN) return (unsigned)arg ? m_fail(EINVAL) : m_run(f);\n    }\n    return m_fail(ENOTTY);\n}\nvoid *__wrap_mmap(void *addr, size_t len, int prot, int flags, int fd, off_t off) {\n    struct m_fd *f = (flags & MAP_ANONYMOUS) ? NULL : m_get(fd);\n    if (f && f->kind != K_VCPU) { errno = ENODEV; return MAP_FAILED; }\n    if (f && (off != 0 || len == 0 || len > 3 * PG)) { errno = EINVAL; return MAP_FAILED; }\n    if (!f && (flags & MAP_ANONYMOUS) == 0) return __real_mmap(addr, len, prot, flags, fd, off);\n    void *p = __real_mmap(f ? NULL : addr, f ? 3 * PG : len, f ? PROT_READ | PROT_WRITE : prot,\n                          f ? MAP_SHARED | MAP_ANONYMOUS : flags, f ? -1 : fd, f ? 0 : off);\n    if (p == MAP_FAILED) return p;\n    for (int i = 0; i < 32; i++)\n        if (!m_maps[i].a) { m_maps[i].a = p; m_maps[i].l = len; break; }\n    if (f) { f->run = p; f->runlen = len; }\n    return p;\n}\nint __wrap_munmap(void *addr, size_t len) {\n    int r = __real_munmap(addr, len);\n    if (r == 0)\n        for (int i = 0; i < 32; i++)\n            if (m_maps[i].a == addr) {\n                m_maps[i].a = NULL;\n                for (int k = 0; k < M_FDS; k++) if (m_fds[k].run == addr) m_fds[k].run = NULL;\n                break;\n            }\n    return r;\n}\n\n/* ---- helpers of the driver ---- */\nstatic void m_reset(void) {\n    memset(m_fds, 0, sizeof m_fds); memset(m_vms, 0, sizeof m_vms); memset(m_maps, 0, sizeof m_maps);\n    m_nvm = 0; m_open_err = 0; m_api = 12; m_vm_err = 0; m_runs = 0; m_opens = 0; m_oflags = 0; m_eintr = 0;\n}\nstatic const char *m_en(int e) {\n    switch (e) {\n    case ENOENT: return \"ENOENT\"; case EACCES: return \"EACCES\"; case EINVAL: return \"EINVAL\";\n    case EEXIST: return \"EEXIST\"; case EBADF: return \"EBADF\"; case EINTR: return \"EINTR\";\n    case EMFILE: return \"EMFILE\"; case ENOMEM: return \"ENOMEM\"; case EPROTO: return \"EPROTO\";\n    case E2BIG: return \"E2BIG\"; case EIO: return \"EIO\"; case ENOTTY: return \"ENOTTY\";\n    case EFAULT: return \"EFAULT\"; case ENODEV: return \"ENODEV\"; case EPERM: return \"EPERM\";\n    }\n    return \"E?\";\n}\nstatic void m_pr(const char *label, long r) {\n    if (r < 0 && r > -4096) printf(\"%s: -%s\\n\", label, m_en((int)-r));\n    else printf(\"%s: %ld\\n\", label, r);\n}\n/* print the result of a raw ioctl/mmap-like call that reports errors through errno */\nstatic void m_pre(const char *label, long r) {\n    int e = errno;\n    if (r < 0) printf(\"%s: -%s\\n\", label, m_en(e));\n    else printf(\"%s: %ld\\n\", label, r);\n}\nstatic void m_leaks(void) { printf(\"leaks: fds=%d maps=%d\\n\", m_nopen(), m_nmaps()); }\nstatic const char *m_kind(int fd) {\n    struct m_fd *f = m_get(fd);\n    return !f ? \"none\" : f->kind == K_SYS ? \"system\" : f->kind == K_VM ? \"vm\" : \"vcpu\";\n}\n/* driver-side setup of a VM with the guest program at guest address 0 and one vCPU mapped for KVM_RUN */\nstatic uint8_t *m_boot(const uint8_t *prog, int len, int *vcpu, struct kvm_run **run) {\n    int kvm = open(\"/dev/kvm\", O_RDWR | O_CLOEXEC);\n    int vm = ioctl(kvm, KVM_CREATE_VM, 0);\n    uint8_t *mem = mmap(NULL, PG, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);\n    memcpy(mem, prog, len);\n    struct kvm_userspace_memory_region r = { .slot = 0, .guest_phys_addr = 0, .memory_size = PG, .userspace_addr = (uintptr_t)mem };\n    ioctl(vm, KVM_SET_USER_MEMORY_REGION, &r);\n    *vcpu = ioctl(vm, KVM_CREATE_VCPU, 0);\n    *run = mmap(NULL, 3 * PG, PROT_READ | PROT_WRITE, MAP_SHARED, *vcpu, 0);\n    return mem;\n}\n\n\nint main(void) {\n    m_reset();\n    int fd = kvm_open();\n    printf(\"normal: kind=%s\\n\", m_kind(fd));\n    close(fd);\n    m_leaks();\n    m_reset(); m_open_err = ENOENT;\n    m_pr(\"module not loaded\", kvm_open());\n    m_leaks();\n    m_reset(); m_open_err = EACCES;\n    m_pr(\"not in the kvm group\", kvm_open());\n    m_reset(); m_api = 11;\n    m_pr(\"version 11\", kvm_open());\n    m_leaks();\n    m_reset(); m_api = 13;\n    m_pr(\"version 13\", kvm_open());\n    m_leaks();\n    return 0;\n}\n", "expected": ["normal: kind=system", "leaks: fds=0 maps=0", "module not loaded: -ENOENT", "leaks: fds=0 maps=0", "not in the kvm group: -EACCES", "version 11: -EPROTO", "leaks: fds=0 maps=0", "version 13: -EPROTO", "leaks: fds=0 maps=0"], "flags": "-std=gnu11 -O1 -Wall -Wl,--wrap=open,--wrap=ioctl,--wrap=close,--wrap=mmap,--wrap=munmap"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 28, 'la28-extensions', 2, 'c', 'Расширения KVM', 'Прежде чем пользоваться возможностью, VMM спрашивает ядро через ioctl(kvm, KVM_CHECK_EXTENSION, cap): 0 значит «не поддерживается», положительное число значит «поддерживается» (иногда число несёт данные, например сколько vCPU разрешено). Напишите две функции. int kvm_cap_value(int kvm, int cap): верните результат вызова или -errno при ошибке. int kvm_missing(int kvm, const int *caps, int n, int *missing): запишите в missing (по порядку) те возможности из caps, которые не поддерживаются, и верните их число; если какой-то вызов завершился ошибкой, сразу верните -errno. Устройства /dev/kvm в песочнице нет: драйвер подставляет МОДЕЛЬ ядра (лабораторное упрощение, константы и структуры настоящие, из linux/kvm.h; поведение модели описано в условии). Пишите обычный код с open, ioctl, close, mmap, как для настоящего устройства.', '#include <errno.h>
#include <fcntl.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/kvm.h>

int kvm_cap_value(int kvm, int cap) {
    // KVM_CHECK_EXTENSION
    return -1;
}

int kvm_missing(int kvm, const int *caps, int n, int *missing) {
    // собрать неподдерживаемые
    return -1;
}
', 'kvm_missing удобно написать поверх kvm_cap_value. Ошибка — отрицательное значение, а «не поддерживается» — ровно ноль.', '{"driver": "/*__DRIVER__*/\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <stdint.h>\n#include <stdarg.h>\n#include <errno.h>\n#include <fcntl.h>\n#include <unistd.h>\n#include <sys/mman.h>\n#include <sys/ioctl.h>\n#include <linux/kvm.h>\n\n/* ---- LAB MODEL of /dev/kvm: a fake kernel behind the linker''s --wrap (the sandbox has no /dev/kvm) ---- */\nextern int __real_open(const char *, int, ...);\nextern int __real_close(int);\nextern void *__real_mmap(void *, size_t, int, int, int, off_t);\nextern int __real_munmap(void *, size_t);\n\n#define PG 4096UL\n#define M_FDS 16\n#define M_SLOTS 32\n#define M_MAXV 8\nenum { K_FREE, K_SYS, K_VM, K_VCPU };\nstruct m_slot { int used; uint64_t gpa, size, uaddr; };\nstruct m_vm { struct m_slot s[M_SLOTS]; int nv; int ids[M_MAXV]; };\nstruct m_fd { int kind, vm, id; struct kvm_run *run; size_t runlen; uint64_t pc; uint8_t acc; int pend; };\nstatic struct m_fd m_fds[M_FDS];\nstatic struct m_vm m_vms[4];\nstatic int m_nvm;\nstatic struct { void *a; size_t l; } m_maps[32];\nstatic int m_open_err, m_api = 12, m_vm_err, m_runs, m_opens, m_oflags;\nstatic unsigned m_eintr; /* bit k set: the (k+1)-th KVM_RUN fails with EINTR */\n\nstatic int m_fail(int e) { errno = e; return -1; }\nstatic struct m_fd *m_get(int fd) {\n    int i = fd - 100;\n    return (i < 0 || i >= M_FDS || m_fds[i].kind == K_FREE) ? NULL : &m_fds[i];\n}\nstatic int m_alloc(int kind, int vm, int id) {\n    for (int i = 0; i < M_FDS; i++)\n        if (m_fds[i].kind == K_FREE) {\n            memset(&m_fds[i], 0, sizeof m_fds[i]);\n            m_fds[i].kind = kind; m_fds[i].vm = vm; m_fds[i].id = id;\n            return 100 + i;\n        }\n    return -1;\n}\nstatic int m_nopen(void) { int n = 0; for (int i = 0; i < M_FDS; i++) n += m_fds[i].kind != K_FREE; return n; }\nstatic int m_nmaps(void) { int n = 0; for (int i = 0; i < 32; i++) n += m_maps[i].a != NULL; return n; }\nstatic long m_cap(unsigned long c) {\n    switch (c) {\n    case KVM_CAP_USER_MEMORY: case KVM_CAP_IMMEDIATE_EXIT: case KVM_CAP_MP_STATE:\n    case KVM_CAP_IOEVENTFD: case KVM_CAP_IRQFD: return 1;\n    case KVM_CAP_NR_VCPUS: return 4;\n    case KVM_CAP_MAX_VCPUS: return M_MAXV;\n    case KVM_CAP_NR_MEMSLOTS: return M_SLOTS;\n    default: return 0;\n    }\n}\nstatic int m_gread(struct m_vm *v, uint64_t gpa, uint8_t *out, int n) {\n    for (int k = 0; k < n; k++) {\n        int ok = 0;\n        for (int i = 0; i < M_SLOTS && !ok; i++) {\n            struct m_slot *s = &v->s[i];\n            if (s->used && gpa + k >= s->gpa && gpa + k < s->gpa + s->size) {\n                out[k] = ((uint8_t *)(uintptr_t)s->uaddr)[gpa + k - s->gpa];\n                ok = 1;\n            }\n        }\n        if (!ok) return -1;\n    }\n    return 0;\n}\n/* the toy guest: opcode lengths; this is NOT machine code, it is the lab''s own tiny instruction set */\nstatic int m_oplen(int op) {\n    switch (op) {\n    case 0x00: case 0xFF: return 1;\n    case 0x01: return 4;  /* OUT port,imm8 */\n    case 0x02: return 3;  /* IN port -> acc */\n    case 0x03: return 6;  /* MMIO write addr32,imm8 */\n    case 0x04: return 5;  /* MMIO read addr32 -> acc */\n    case 0x05: return 3;  /* OUT port,acc */\n    case 0x06: return 2;  /* acc += imm8 */\n    default: return 0;\n    }\n}\nstatic int m_run(struct m_fd *f) {\n    struct m_vm *v = &m_vms[f->vm];\n    struct kvm_run *r = f->run;\n    if (!r) return m_fail(EINVAL);\n    uint8_t *pio = (uint8_t *)r + PG;\n    m_runs++;\n    if ((m_runs <= 31 && ((m_eintr >> (m_runs - 1)) & 1)) || r->immediate_exit) {\n        r->exit_reason = KVM_EXIT_INTR;\n        return m_fail(EINTR);\n    }\n    if (f->pend == 1) f->acc = pio[0];\n    if (f->pend == 2) f->acc = r->mmio.data[0];\n    f->pend = 0;\n    for (;;) {\n        uint8_t b[8];\n        int n;\n        if (m_gread(v, f->pc, b, 1)) { r->exit_reason = KVM_EXIT_FAIL_ENTRY; r->fail_entry.hardware_entry_failure_reason = 0x1000; r->fail_entry.cpu = 0; return 0; }\n        n = m_oplen(b[0]);\n        if (n == 0) {\n            r->exit_reason = KVM_EXIT_INTERNAL_ERROR;\n            r->internal.suberror = KVM_INTERNAL_ERROR_EMULATION;\n            r->internal.ndata = 0;\n            return 0;\n        }\n        if (m_gread(v, f->pc, b, n)) { r->exit_reason = KVM_EXIT_FAIL_ENTRY; r->fail_entry.hardware_entry_failure_reason = 0x1000; r->fail_entry.cpu = 0; return 0; }\n        f->pc += n;\n        switch (b[0]) {\n        case 0x00: r->exit_reason = KVM_EXIT_HLT; return 0;\n        case 0xFF: r->exit_reason = KVM_EXIT_SHUTDOWN; return 0;\n        case 0x06: f->acc = (uint8_t)(f->acc + b[1]); break;\n        case 0x01: case 0x05:\n            if (f->runlen < 2 * PG) return m_fail(EFAULT);\n            r->exit_reason = KVM_EXIT_IO;\n            r->io.direction = KVM_EXIT_IO_OUT; r->io.size = 1; r->io.count = 1;\n            r->io.port = (uint16_t)(b[1] | b[2] << 8); r->io.data_offset = PG;\n            pio[0] = b[0] == 0x01 ? b[3] : f->acc;\n            return 0;\n        case 0x02:\n            if (f->runlen < 2 * PG) return m_fail(EFAULT);\n            r->exit_reason = KVM_EXIT_IO;\n            r->io.direction = KVM_EXIT_IO_IN; r->io.size = 1; r->io.count = 1;\n            r->io.port = (uint16_t)(b[1] | b[2] << 8); r->io.data_offset = PG;\n            pio[0] = 0; f->pend = 1;\n            return 0;\n        case 0x03: case 0x04:\n            r->exit_reason = KVM_EXIT_MMIO;\n            r->mmio.phys_addr = (uint32_t)b[1] | (uint32_t)b[2] << 8 | (uint32_t)b[3] << 16 | (uint32_t)b[4] << 24;\n            memset(r->mmio.data, 0, 8);\n            r->mmio.len = 1;\n            if (b[0] == 0x03) { r->mmio.is_write = 1; r->mmio.data[0] = b[5]; }\n            else { r->mmio.is_write = 0; f->pend = 2; }\n            return 0;\n        }\n    }\n}\nstatic int m_set_region(struct m_fd *f, struct kvm_userspace_memory_region *m) {\n    struct m_vm *v = &m_vms[f->vm];\n    unsigned slot = m->slot & 0xffff;\n    if (m->flags & ~(KVM_MEM_LOG_DIRTY_PAGES | KVM_MEM_READONLY)) return m_fail(EINVAL);\n    if ((m->memory_size & (PG - 1)) || (m->guest_phys_addr & (PG - 1)) || (m->userspace_addr & (PG - 1))) return m_fail(EINVAL);\n    if ((m->slot >> 16) != 0 || slot >= M_SLOTS) return m_fail(EINVAL);\n    if (m->guest_phys_addr + m->memory_size < m->guest_phys_addr) return m_fail(EINVAL);\n    struct m_slot *s = &v->s[slot];\n    if (m->memory_size == 0) {\n        if (!s->used) return m_fail(EINVAL);\n        s->used = 0;\n        return 0;\n    }\n    if (s->used && (m->userspace_addr != s->uaddr || m->memory_size != s->size)) return m_fail(EINVAL);\n    for (int i = 0; i < M_SLOTS; i++)\n        if (i != (int)slot && v->s[i].used && m->guest_phys_addr < v->s[i].gpa + v->s[i].size &&\n            v->s[i].gpa < m->guest_phys_addr + m->memory_size)\n            return m_fail(EEXIST);\n    s->used = 1; s->gpa = m->guest_phys_addr; s->size = m->memory_size; s->uaddr = m->userspace_addr;\n    return 0;\n}\nint __wrap_open(const char *path, int flags, ...) {\n    if (strcmp(path, \"/dev/kvm\") == 0) {\n        m_opens++; m_oflags = flags;\n        if (m_open_err) return m_fail(m_open_err);\n        int fd = m_alloc(K_SYS, 0, 0);\n        return fd < 0 ? m_fail(EMFILE) : fd;\n    }\n    va_list ap; va_start(ap, flags);\n    int mode = (flags & O_CREAT) ? va_arg(ap, int) : 0;\n    va_end(ap);\n    return __real_open(path, flags, mode);\n}\nint __wrap_close(int fd) {\n    struct m_fd *f = m_get(fd);\n    if (!f) return __real_close(fd);\n    f->kind = K_FREE;\n    return 0;\n}\nint __wrap_ioctl(int fd, unsigned long req, ...) {\n    va_list ap; va_start(ap, req);\n    unsigned long arg = va_arg(ap, unsigned long);\n    va_end(ap);\n    struct m_fd *f = m_get(fd);\n    if (!f) return m_fail(EBADF);\n    if (f->kind == K_SYS) {\n        if (req == KVM_GET_API_VERSION) return (unsigned)arg ? m_fail(EINVAL) : m_api;\n        if (req == KVM_CHECK_EXTENSION) return (int)m_cap((unsigned)arg);\n        if (req == KVM_GET_VCPU_MMAP_SIZE) return (unsigned)arg ? m_fail(EINVAL) : (int)(3 * PG);\n        if (req == KVM_CREATE_VM) {\n            if (m_vm_err) return m_fail(m_vm_err);\n            if ((unsigned)arg != 0 || m_nvm >= 4) return m_fail(EINVAL);\n            int nfd = m_alloc(K_VM, m_nvm, 0);\n            if (nfd < 0) return m_fail(EMFILE);\n            m_nvm++;\n            return nfd;\n        }\n    } else if (f->kind == K_VM) {\n        struct m_vm *v = &m_vms[f->vm];\n        if (req == KVM_CHECK_EXTENSION) return (int)m_cap((unsigned)arg);\n        if (req == KVM_CREATE_VCPU) {\n            if (v->nv >= M_MAXV) return m_fail(EINVAL);\n            for (int i = 0; i < v->nv; i++) if (v->ids[i] == (int)(unsigned)arg) return m_fail(EEXIST);\n            int nfd = m_alloc(K_VCPU, f->vm, (int)(unsigned)arg);\n            if (nfd < 0) return m_fail(EMFILE);\n            v->ids[v->nv++] = (int)(unsigned)arg;\n            return nfd;\n        }\n        if (req == KVM_SET_USER_MEMORY_REGION) {\n            if (arg == 0) return m_fail(EFAULT);\n            return m_set_region(f, (struct kvm_userspace_memory_region *)arg);\n        }\n    } else if (f->kind == K_VCPU) {\n        if (req == KVM_RUN) return (unsigned)arg ? m_fail(EINVAL) : m_run(f);\n    }\n    return m_fail(ENOTTY);\n}\nvoid *__wrap_mmap(void *addr, size_t len, int prot, int flags, int fd, off_t off) {\n    struct m_fd *f = (flags & MAP_ANONYMOUS) ? NULL : m_get(fd);\n    if (f && f->kind != K_VCPU) { errno = ENODEV; return MAP_FAILED; }\n    if (f && (off != 0 || len == 0 || len > 3 * PG)) { errno = EINVAL; return MAP_FAILED; }\n    if (!f && (flags & MAP_ANONYMOUS) == 0) return __real_mmap(addr, len, prot, flags, fd, off);\n    void *p = __real_mmap(f ? NULL : addr, f ? 3 * PG : len, f ? PROT_READ | PROT_WRITE : prot,\n                          f ? MAP_SHARED | MAP_ANONYMOUS : flags, f ? -1 : fd, f ? 0 : off);\n    if (p == MAP_FAILED) return p;\n    for (int i = 0; i < 32; i++)\n        if (!m_maps[i].a) { m_maps[i].a = p; m_maps[i].l = len; break; }\n    if (f) { f->run = p; f->runlen = len; }\n    return p;\n}\nint __wrap_munmap(void *addr, size_t len) {\n    int r = __real_munmap(addr, len);\n    if (r == 0)\n        for (int i = 0; i < 32; i++)\n            if (m_maps[i].a == addr) {\n                m_maps[i].a = NULL;\n                for (int k = 0; k < M_FDS; k++) if (m_fds[k].run == addr) m_fds[k].run = NULL;\n                break;\n            }\n    return r;\n}\n\n/* ---- helpers of the driver ---- */\nstatic void m_reset(void) {\n    memset(m_fds, 0, sizeof m_fds); memset(m_vms, 0, sizeof m_vms); memset(m_maps, 0, sizeof m_maps);\n    m_nvm = 0; m_open_err = 0; m_api = 12; m_vm_err = 0; m_runs = 0; m_opens = 0; m_oflags = 0; m_eintr = 0;\n}\nstatic const char *m_en(int e) {\n    switch (e) {\n    case ENOENT: return \"ENOENT\"; case EACCES: return \"EACCES\"; case EINVAL: return \"EINVAL\";\n    case EEXIST: return \"EEXIST\"; case EBADF: return \"EBADF\"; case EINTR: return \"EINTR\";\n    case EMFILE: return \"EMFILE\"; case ENOMEM: return \"ENOMEM\"; case EPROTO: return \"EPROTO\";\n    case E2BIG: return \"E2BIG\"; case EIO: return \"EIO\"; case ENOTTY: return \"ENOTTY\";\n    case EFAULT: return \"EFAULT\"; case ENODEV: return \"ENODEV\"; case EPERM: return \"EPERM\";\n    }\n    return \"E?\";\n}\nstatic void m_pr(const char *label, long r) {\n    if (r < 0 && r > -4096) printf(\"%s: -%s\\n\", label, m_en((int)-r));\n    else printf(\"%s: %ld\\n\", label, r);\n}\n/* print the result of a raw ioctl/mmap-like call that reports errors through errno */\nstatic void m_pre(const char *label, long r) {\n    int e = errno;\n    if (r < 0) printf(\"%s: -%s\\n\", label, m_en(e));\n    else printf(\"%s: %ld\\n\", label, r);\n}\nstatic void m_leaks(void) { printf(\"leaks: fds=%d maps=%d\\n\", m_nopen(), m_nmaps()); }\nstatic const char *m_kind(int fd) {\n    struct m_fd *f = m_get(fd);\n    return !f ? \"none\" : f->kind == K_SYS ? \"system\" : f->kind == K_VM ? \"vm\" : \"vcpu\";\n}\n/* driver-side setup of a VM with the guest program at guest address 0 and one vCPU mapped for KVM_RUN */\nstatic uint8_t *m_boot(const uint8_t *prog, int len, int *vcpu, struct kvm_run **run) {\n    int kvm = open(\"/dev/kvm\", O_RDWR | O_CLOEXEC);\n    int vm = ioctl(kvm, KVM_CREATE_VM, 0);\n    uint8_t *mem = mmap(NULL, PG, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);\n    memcpy(mem, prog, len);\n    struct kvm_userspace_memory_region r = { .slot = 0, .guest_phys_addr = 0, .memory_size = PG, .userspace_addr = (uintptr_t)mem };\n    ioctl(vm, KVM_SET_USER_MEMORY_REGION, &r);\n    *vcpu = ioctl(vm, KVM_CREATE_VCPU, 0);\n    *run = mmap(NULL, 3 * PG, PROT_READ | PROT_WRITE, MAP_SHARED, *vcpu, 0);\n    return mem;\n}\n\n\nint main(void) {\n    m_reset();\n    int kvm = open(\"/dev/kvm\", O_RDWR | O_CLOEXEC);\n    m_pr(\"user memory\", kvm_cap_value(kvm, KVM_CAP_USER_MEMORY));\n    m_pr(\"recommended vcpus\", kvm_cap_value(kvm, KVM_CAP_NR_VCPUS));\n    m_pr(\"max vcpus\", kvm_cap_value(kvm, KVM_CAP_MAX_VCPUS));\n    m_pr(\"memory slots\", kvm_cap_value(kvm, KVM_CAP_NR_MEMSLOTS));\n    m_pr(\"one reg\", kvm_cap_value(kvm, KVM_CAP_ONE_REG));\n    int caps[] = { KVM_CAP_USER_MEMORY, KVM_CAP_ONE_REG, KVM_CAP_IMMEDIATE_EXIT, KVM_CAP_IRQFD_RESAMPLE, KVM_CAP_MP_STATE };\n    int miss[8];\n    int n = kvm_missing(kvm, caps, 5, miss);\n    printf(\"missing %d:\", n);\n    for (int i = 0; i < n; i++) printf(\" %d\", miss[i]);\n    printf(\"\\n\");\n    n = kvm_missing(kvm, caps, 0, miss);\n    printf(\"none asked: %d\\n\", n);\n    m_pr(\"bad fd\", kvm_cap_value(-1, KVM_CAP_USER_MEMORY));\n    m_pr(\"bad fd list\", kvm_missing(-1, caps, 5, miss));\n    int vm = ioctl(kvm, KVM_CREATE_VM, 0);\n    m_pr(\"same question on the vm fd\", kvm_cap_value(vm, KVM_CAP_NR_MEMSLOTS));\n    return 0;\n}\n", "expected": ["user memory: 1", "recommended vcpus: 4", "max vcpus: 8", "memory slots: 32", "one reg: 0", "missing 2: 70 82", "none asked: 0", "bad fd: -EBADF", "bad fd list: -EBADF", "same question on the vm fd: 32"], "flags": "-std=gnu11 -O1 -Wall -Wl,--wrap=open,--wrap=ioctl,--wrap=close,--wrap=mmap,--wrap=munmap"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 28, 'la28-create-vm', 3, 'c', 'ВМ и vCPU: три уровня дескрипторов', 'У KVM три уровня дескрипторов: системный (/dev/kvm), ВМ (его даёт KVM_CREATE_VM) и vCPU (его даёт KVM_CREATE_VCPU, вызванный на дескрипторе ВМ). Напишите int vm_create(int kvm, int nvcpus, int *vcpu_fds): создайте ВМ ioctl(kvm, KVM_CREATE_VM, 0) и nvcpus виртуальных процессоров с номерами 0, 1, ..., nvcpus-1 через ioctl(vm, KVM_CREATE_VCPU, номер). Дескрипторы vCPU запишите в vcpu_fds, верните дескриптор ВМ. Если что-то не удалось, закройте всё, что успели открыть в этой функции (дескриптор kvm не ваш, его не закрывайте), и верните -errno. В модели vCPU не больше восьми (девятый даёт EINVAL), повторный номер даёт EEXIST. Запрос не того уровня (например, KVM_RUN на дескрипторе ВМ) модель отклоняет с ENOTTY; настоящее ядро в таком случае отвечает ENOTTY или EINVAL в зависимости от дескриптора и архитектуры. Устройства /dev/kvm в песочнице нет: драйвер подставляет МОДЕЛЬ ядра (лабораторное упрощение, константы и структуры настоящие, из linux/kvm.h; поведение модели описано в условии). Пишите обычный код с open, ioctl, close, mmap, как для настоящего устройства.', '#include <errno.h>
#include <fcntl.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/kvm.h>

int vm_create(int kvm, int nvcpus, int *vcpu_fds) {
    // KVM_CREATE_VM, затем KVM_CREATE_VCPU для 0..nvcpus-1
    return -1;
}
', 'Номер vCPU — третий аргумент ioctl. При ошибке на i-м vCPU закройте предыдущие i штук и саму ВМ, сохранив errno до close.', '{"driver": "/*__DRIVER__*/\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <stdint.h>\n#include <stdarg.h>\n#include <errno.h>\n#include <fcntl.h>\n#include <unistd.h>\n#include <sys/mman.h>\n#include <sys/ioctl.h>\n#include <linux/kvm.h>\n\n/* ---- LAB MODEL of /dev/kvm: a fake kernel behind the linker''s --wrap (the sandbox has no /dev/kvm) ---- */\nextern int __real_open(const char *, int, ...);\nextern int __real_close(int);\nextern void *__real_mmap(void *, size_t, int, int, int, off_t);\nextern int __real_munmap(void *, size_t);\n\n#define PG 4096UL\n#define M_FDS 16\n#define M_SLOTS 32\n#define M_MAXV 8\nenum { K_FREE, K_SYS, K_VM, K_VCPU };\nstruct m_slot { int used; uint64_t gpa, size, uaddr; };\nstruct m_vm { struct m_slot s[M_SLOTS]; int nv; int ids[M_MAXV]; };\nstruct m_fd { int kind, vm, id; struct kvm_run *run; size_t runlen; uint64_t pc; uint8_t acc; int pend; };\nstatic struct m_fd m_fds[M_FDS];\nstatic struct m_vm m_vms[4];\nstatic int m_nvm;\nstatic struct { void *a; size_t l; } m_maps[32];\nstatic int m_open_err, m_api = 12, m_vm_err, m_runs, m_opens, m_oflags;\nstatic unsigned m_eintr; /* bit k set: the (k+1)-th KVM_RUN fails with EINTR */\n\nstatic int m_fail(int e) { errno = e; return -1; }\nstatic struct m_fd *m_get(int fd) {\n    int i = fd - 100;\n    return (i < 0 || i >= M_FDS || m_fds[i].kind == K_FREE) ? NULL : &m_fds[i];\n}\nstatic int m_alloc(int kind, int vm, int id) {\n    for (int i = 0; i < M_FDS; i++)\n        if (m_fds[i].kind == K_FREE) {\n            memset(&m_fds[i], 0, sizeof m_fds[i]);\n            m_fds[i].kind = kind; m_fds[i].vm = vm; m_fds[i].id = id;\n            return 100 + i;\n        }\n    return -1;\n}\nstatic int m_nopen(void) { int n = 0; for (int i = 0; i < M_FDS; i++) n += m_fds[i].kind != K_FREE; return n; }\nstatic int m_nmaps(void) { int n = 0; for (int i = 0; i < 32; i++) n += m_maps[i].a != NULL; return n; }\nstatic long m_cap(unsigned long c) {\n    switch (c) {\n    case KVM_CAP_USER_MEMORY: case KVM_CAP_IMMEDIATE_EXIT: case KVM_CAP_MP_STATE:\n    case KVM_CAP_IOEVENTFD: case KVM_CAP_IRQFD: return 1;\n    case KVM_CAP_NR_VCPUS: return 4;\n    case KVM_CAP_MAX_VCPUS: return M_MAXV;\n    case KVM_CAP_NR_MEMSLOTS: return M_SLOTS;\n    default: return 0;\n    }\n}\nstatic int m_gread(struct m_vm *v, uint64_t gpa, uint8_t *out, int n) {\n    for (int k = 0; k < n; k++) {\n        int ok = 0;\n        for (int i = 0; i < M_SLOTS && !ok; i++) {\n            struct m_slot *s = &v->s[i];\n            if (s->used && gpa + k >= s->gpa && gpa + k < s->gpa + s->size) {\n                out[k] = ((uint8_t *)(uintptr_t)s->uaddr)[gpa + k - s->gpa];\n                ok = 1;\n            }\n        }\n        if (!ok) return -1;\n    }\n    return 0;\n}\n/* the toy guest: opcode lengths; this is NOT machine code, it is the lab''s own tiny instruction set */\nstatic int m_oplen(int op) {\n    switch (op) {\n    case 0x00: case 0xFF: return 1;\n    case 0x01: return 4;  /* OUT port,imm8 */\n    case 0x02: return 3;  /* IN port -> acc */\n    case 0x03: return 6;  /* MMIO write addr32,imm8 */\n    case 0x04: return 5;  /* MMIO read addr32 -> acc */\n    case 0x05: return 3;  /* OUT port,acc */\n    case 0x06: return 2;  /* acc += imm8 */\n    default: return 0;\n    }\n}\nstatic int m_run(struct m_fd *f) {\n    struct m_vm *v = &m_vms[f->vm];\n    struct kvm_run *r = f->run;\n    if (!r) return m_fail(EINVAL);\n    uint8_t *pio = (uint8_t *)r + PG;\n    m_runs++;\n    if ((m_runs <= 31 && ((m_eintr >> (m_runs - 1)) & 1)) || r->immediate_exit) {\n        r->exit_reason = KVM_EXIT_INTR;\n        return m_fail(EINTR);\n    }\n    if (f->pend == 1) f->acc = pio[0];\n    if (f->pend == 2) f->acc = r->mmio.data[0];\n    f->pend = 0;\n    for (;;) {\n        uint8_t b[8];\n        int n;\n        if (m_gread(v, f->pc, b, 1)) { r->exit_reason = KVM_EXIT_FAIL_ENTRY; r->fail_entry.hardware_entry_failure_reason = 0x1000; r->fail_entry.cpu = 0; return 0; }\n        n = m_oplen(b[0]);\n        if (n == 0) {\n            r->exit_reason = KVM_EXIT_INTERNAL_ERROR;\n            r->internal.suberror = KVM_INTERNAL_ERROR_EMULATION;\n            r->internal.ndata = 0;\n            return 0;\n        }\n        if (m_gread(v, f->pc, b, n)) { r->exit_reason = KVM_EXIT_FAIL_ENTRY; r->fail_entry.hardware_entry_failure_reason = 0x1000; r->fail_entry.cpu = 0; return 0; }\n        f->pc += n;\n        switch (b[0]) {\n        case 0x00: r->exit_reason = KVM_EXIT_HLT; return 0;\n        case 0xFF: r->exit_reason = KVM_EXIT_SHUTDOWN; return 0;\n        case 0x06: f->acc = (uint8_t)(f->acc + b[1]); break;\n        case 0x01: case 0x05:\n            if (f->runlen < 2 * PG) return m_fail(EFAULT);\n            r->exit_reason = KVM_EXIT_IO;\n            r->io.direction = KVM_EXIT_IO_OUT; r->io.size = 1; r->io.count = 1;\n            r->io.port = (uint16_t)(b[1] | b[2] << 8); r->io.data_offset = PG;\n            pio[0] = b[0] == 0x01 ? b[3] : f->acc;\n            return 0;\n        case 0x02:\n            if (f->runlen < 2 * PG) return m_fail(EFAULT);\n            r->exit_reason = KVM_EXIT_IO;\n            r->io.direction = KVM_EXIT_IO_IN; r->io.size = 1; r->io.count = 1;\n            r->io.port = (uint16_t)(b[1] | b[2] << 8); r->io.data_offset = PG;\n            pio[0] = 0; f->pend = 1;\n            return 0;\n        case 0x03: case 0x04:\n            r->exit_reason = KVM_EXIT_MMIO;\n            r->mmio.phys_addr = (uint32_t)b[1] | (uint32_t)b[2] << 8 | (uint32_t)b[3] << 16 | (uint32_t)b[4] << 24;\n            memset(r->mmio.data, 0, 8);\n            r->mmio.len = 1;\n            if (b[0] == 0x03) { r->mmio.is_write = 1; r->mmio.data[0] = b[5]; }\n            else { r->mmio.is_write = 0; f->pend = 2; }\n            return 0;\n        }\n    }\n}\nstatic int m_set_region(struct m_fd *f, struct kvm_userspace_memory_region *m) {\n    struct m_vm *v = &m_vms[f->vm];\n    unsigned slot = m->slot & 0xffff;\n    if (m->flags & ~(KVM_MEM_LOG_DIRTY_PAGES | KVM_MEM_READONLY)) return m_fail(EINVAL);\n    if ((m->memory_size & (PG - 1)) || (m->guest_phys_addr & (PG - 1)) || (m->userspace_addr & (PG - 1))) return m_fail(EINVAL);\n    if ((m->slot >> 16) != 0 || slot >= M_SLOTS) return m_fail(EINVAL);\n    if (m->guest_phys_addr + m->memory_size < m->guest_phys_addr) return m_fail(EINVAL);\n    struct m_slot *s = &v->s[slot];\n    if (m->memory_size == 0) {\n        if (!s->used) return m_fail(EINVAL);\n        s->used = 0;\n        return 0;\n    }\n    if (s->used && (m->userspace_addr != s->uaddr || m->memory_size != s->size)) return m_fail(EINVAL);\n    for (int i = 0; i < M_SLOTS; i++)\n        if (i != (int)slot && v->s[i].used && m->guest_phys_addr < v->s[i].gpa + v->s[i].size &&\n            v->s[i].gpa < m->guest_phys_addr + m->memory_size)\n            return m_fail(EEXIST);\n    s->used = 1; s->gpa = m->guest_phys_addr; s->size = m->memory_size; s->uaddr = m->userspace_addr;\n    return 0;\n}\nint __wrap_open(const char *path, int flags, ...) {\n    if (strcmp(path, \"/dev/kvm\") == 0) {\n        m_opens++; m_oflags = flags;\n        if (m_open_err) return m_fail(m_open_err);\n        int fd = m_alloc(K_SYS, 0, 0);\n        return fd < 0 ? m_fail(EMFILE) : fd;\n    }\n    va_list ap; va_start(ap, flags);\n    int mode = (flags & O_CREAT) ? va_arg(ap, int) : 0;\n    va_end(ap);\n    return __real_open(path, flags, mode);\n}\nint __wrap_close(int fd) {\n    struct m_fd *f = m_get(fd);\n    if (!f) return __real_close(fd);\n    f->kind = K_FREE;\n    return 0;\n}\nint __wrap_ioctl(int fd, unsigned long req, ...) {\n    va_list ap; va_start(ap, req);\n    unsigned long arg = va_arg(ap, unsigned long);\n    va_end(ap);\n    struct m_fd *f = m_get(fd);\n    if (!f) return m_fail(EBADF);\n    if (f->kind == K_SYS) {\n        if (req == KVM_GET_API_VERSION) return (unsigned)arg ? m_fail(EINVAL) : m_api;\n        if (req == KVM_CHECK_EXTENSION) return (int)m_cap((unsigned)arg);\n        if (req == KVM_GET_VCPU_MMAP_SIZE) return (unsigned)arg ? m_fail(EINVAL) : (int)(3 * PG);\n        if (req == KVM_CREATE_VM) {\n            if (m_vm_err) return m_fail(m_vm_err);\n            if ((unsigned)arg != 0 || m_nvm >= 4) return m_fail(EINVAL);\n            int nfd = m_alloc(K_VM, m_nvm, 0);\n            if (nfd < 0) return m_fail(EMFILE);\n            m_nvm++;\n            return nfd;\n        }\n    } else if (f->kind == K_VM) {\n        struct m_vm *v = &m_vms[f->vm];\n        if (req == KVM_CHECK_EXTENSION) return (int)m_cap((unsigned)arg);\n        if (req == KVM_CREATE_VCPU) {\n            if (v->nv >= M_MAXV) return m_fail(EINVAL);\n            for (int i = 0; i < v->nv; i++) if (v->ids[i] == (int)(unsigned)arg) return m_fail(EEXIST);\n            int nfd = m_alloc(K_VCPU, f->vm, (int)(unsigned)arg);\n            if (nfd < 0) return m_fail(EMFILE);\n            v->ids[v->nv++] = (int)(unsigned)arg;\n            return nfd;\n        }\n        if (req == KVM_SET_USER_MEMORY_REGION) {\n            if (arg == 0) return m_fail(EFAULT);\n            return m_set_region(f, (struct kvm_userspace_memory_region *)arg);\n        }\n    } else if (f->kind == K_VCPU) {\n        if (req == KVM_RUN) return (unsigned)arg ? m_fail(EINVAL) : m_run(f);\n    }\n    return m_fail(ENOTTY);\n}\nvoid *__wrap_mmap(void *addr, size_t len, int prot, int flags, int fd, off_t off) {\n    struct m_fd *f = (flags & MAP_ANONYMOUS) ? NULL : m_get(fd);\n    if (f && f->kind != K_VCPU) { errno = ENODEV; return MAP_FAILED; }\n    if (f && (off != 0 || len == 0 || len > 3 * PG)) { errno = EINVAL; return MAP_FAILED; }\n    if (!f && (flags & MAP_ANONYMOUS) == 0) return __real_mmap(addr, len, prot, flags, fd, off);\n    void *p = __real_mmap(f ? NULL : addr, f ? 3 * PG : len, f ? PROT_READ | PROT_WRITE : prot,\n                          f ? MAP_SHARED | MAP_ANONYMOUS : flags, f ? -1 : fd, f ? 0 : off);\n    if (p == MAP_FAILED) return p;\n    for (int i = 0; i < 32; i++)\n        if (!m_maps[i].a) { m_maps[i].a = p; m_maps[i].l = len; break; }\n    if (f) { f->run = p; f->runlen = len; }\n    return p;\n}\nint __wrap_munmap(void *addr, size_t len) {\n    int r = __real_munmap(addr, len);\n    if (r == 0)\n        for (int i = 0; i < 32; i++)\n            if (m_maps[i].a == addr) {\n                m_maps[i].a = NULL;\n                for (int k = 0; k < M_FDS; k++) if (m_fds[k].run == addr) m_fds[k].run = NULL;\n                break;\n            }\n    return r;\n}\n\n/* ---- helpers of the driver ---- */\nstatic void m_reset(void) {\n    memset(m_fds, 0, sizeof m_fds); memset(m_vms, 0, sizeof m_vms); memset(m_maps, 0, sizeof m_maps);\n    m_nvm = 0; m_open_err = 0; m_api = 12; m_vm_err = 0; m_runs = 0; m_opens = 0; m_oflags = 0; m_eintr = 0;\n}\nstatic const char *m_en(int e) {\n    switch (e) {\n    case ENOENT: return \"ENOENT\"; case EACCES: return \"EACCES\"; case EINVAL: return \"EINVAL\";\n    case EEXIST: return \"EEXIST\"; case EBADF: return \"EBADF\"; case EINTR: return \"EINTR\";\n    case EMFILE: return \"EMFILE\"; case ENOMEM: return \"ENOMEM\"; case EPROTO: return \"EPROTO\";\n    case E2BIG: return \"E2BIG\"; case EIO: return \"EIO\"; case ENOTTY: return \"ENOTTY\";\n    case EFAULT: return \"EFAULT\"; case ENODEV: return \"ENODEV\"; case EPERM: return \"EPERM\";\n    }\n    return \"E?\";\n}\nstatic void m_pr(const char *label, long r) {\n    if (r < 0 && r > -4096) printf(\"%s: -%s\\n\", label, m_en((int)-r));\n    else printf(\"%s: %ld\\n\", label, r);\n}\n/* print the result of a raw ioctl/mmap-like call that reports errors through errno */\nstatic void m_pre(const char *label, long r) {\n    int e = errno;\n    if (r < 0) printf(\"%s: -%s\\n\", label, m_en(e));\n    else printf(\"%s: %ld\\n\", label, r);\n}\nstatic void m_leaks(void) { printf(\"leaks: fds=%d maps=%d\\n\", m_nopen(), m_nmaps()); }\nstatic const char *m_kind(int fd) {\n    struct m_fd *f = m_get(fd);\n    return !f ? \"none\" : f->kind == K_SYS ? \"system\" : f->kind == K_VM ? \"vm\" : \"vcpu\";\n}\n/* driver-side setup of a VM with the guest program at guest address 0 and one vCPU mapped for KVM_RUN */\nstatic uint8_t *m_boot(const uint8_t *prog, int len, int *vcpu, struct kvm_run **run) {\n    int kvm = open(\"/dev/kvm\", O_RDWR | O_CLOEXEC);\n    int vm = ioctl(kvm, KVM_CREATE_VM, 0);\n    uint8_t *mem = mmap(NULL, PG, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);\n    memcpy(mem, prog, len);\n    struct kvm_userspace_memory_region r = { .slot = 0, .guest_phys_addr = 0, .memory_size = PG, .userspace_addr = (uintptr_t)mem };\n    ioctl(vm, KVM_SET_USER_MEMORY_REGION, &r);\n    *vcpu = ioctl(vm, KVM_CREATE_VCPU, 0);\n    *run = mmap(NULL, 3 * PG, PROT_READ | PROT_WRITE, MAP_SHARED, *vcpu, 0);\n    return mem;\n}\n\n\nint main(void) {\n    int fds[16];\n    m_reset();\n    int kvm = open(\"/dev/kvm\", O_RDWR | O_CLOEXEC);\n    int vm = vm_create(kvm, 2, fds);\n    printf(\"two vcpus: vm=%s vcpu0=%s vcpu1=%s open=%d\\n\", m_kind(vm), m_kind(fds[0]), m_kind(fds[1]), m_nopen());\n    m_pre(\"run on the vm fd\", ioctl(vm, KVM_RUN, 0));\n    m_pre(\"create vcpu on a vcpu fd\", ioctl(fds[0], KVM_CREATE_VCPU, 5));\n    m_pre(\"repeated vcpu id\", ioctl(vm, KVM_CREATE_VCPU, 1));\n    close(fds[0]); close(fds[1]); close(vm);\n    m_reset();\n    kvm = open(\"/dev/kvm\", O_RDWR | O_CLOEXEC);\n    vm = vm_create(kvm, 0, fds);\n    printf(\"no vcpus: vm=%s open=%d\\n\", m_kind(vm), m_nopen());\n    close(vm);\n    m_reset();\n    kvm = open(\"/dev/kvm\", O_RDWR | O_CLOEXEC);\n    m_pr(\"nine vcpus\", vm_create(kvm, 9, fds));\n    printf(\"open after failure: %d\\n\", m_nopen());\n    m_reset(); m_vm_err = ENOMEM;\n    kvm = open(\"/dev/kvm\", O_RDWR | O_CLOEXEC);\n    m_pr(\"create vm fails\", vm_create(kvm, 2, fds));\n    printf(\"open after failure: %d\\n\", m_nopen());\n    return 0;\n}\n", "expected": ["two vcpus: vm=vm vcpu0=vcpu vcpu1=vcpu open=4", "run on the vm fd: -ENOTTY", "create vcpu on a vcpu fd: -ENOTTY", "repeated vcpu id: -EEXIST", "no vcpus: vm=vm open=2", "nine vcpus: -EINVAL", "open after failure: 1", "create vm fails: -ENOMEM", "open after failure: 1"], "flags": "-std=gnu11 -O1 -Wall -Wl,--wrap=open,--wrap=ioctl,--wrap=close,--wrap=mmap,--wrap=munmap"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 28, 'la28-guest-memory', 4, 'c', 'Память гостя: обычный mmap', 'Оперативная память гостя в KVM — это просто память процесса-VMM: вы выделяете её mmap и сообщаете ядру, по какому гостевому физическому адресу она видна. Напишите int guest_mem(int vm, int slot, uint64_t gpa, size_t size, const void *image, size_t len, void **host): округлите size вверх до целых страниц (sysconf(_SC_PAGESIZE)); если len больше округлённого размера, верните -E2BIG, ничего не выделяя; выделите анонимную приватную память mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0), скопируйте в её начало образ (len байт), зарегистрируйте её ioctl(vm, KVM_SET_USER_MEMORY_REGION, &region) со структурой struct kvm_userspace_memory_region (slot, flags = 0, guest_phys_addr = gpa, memory_size, userspace_addr), запишите адрес в *host и верните 0. Если mmap или ioctl не удался, верните -errno, не оставив лишнего отображения (munmap). Модель повторяет проверки ядра: гостевой адрес и размер кратны странице (иначе EINVAL), номер слота меньше 32 (иначе EINVAL), слоты не пересекаются по гостевым адресам (EEXIST). Устройства /dev/kvm в песочнице нет: драйвер подставляет МОДЕЛЬ ядра (лабораторное упрощение, константы и структуры настоящие, из linux/kvm.h; поведение модели описано в условии). Пишите обычный код с open, ioctl, close, mmap, как для настоящего устройства.', '#include <errno.h>
#include <fcntl.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/kvm.h>

int guest_mem(int vm, int slot, uint64_t gpa, size_t size, const void *image, size_t len, void **host) {
    // округлить size, mmap, memcpy, KVM_SET_USER_MEMORY_REGION
    return -1;
}
', 'userspace_addr — это (uintptr_t)указатель, а не указатель. Сохраните errno до munmap.', '{"driver": "/*__DRIVER__*/\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <stdint.h>\n#include <stdarg.h>\n#include <errno.h>\n#include <fcntl.h>\n#include <unistd.h>\n#include <sys/mman.h>\n#include <sys/ioctl.h>\n#include <linux/kvm.h>\n\n/* ---- LAB MODEL of /dev/kvm: a fake kernel behind the linker''s --wrap (the sandbox has no /dev/kvm) ---- */\nextern int __real_open(const char *, int, ...);\nextern int __real_close(int);\nextern void *__real_mmap(void *, size_t, int, int, int, off_t);\nextern int __real_munmap(void *, size_t);\n\n#define PG 4096UL\n#define M_FDS 16\n#define M_SLOTS 32\n#define M_MAXV 8\nenum { K_FREE, K_SYS, K_VM, K_VCPU };\nstruct m_slot { int used; uint64_t gpa, size, uaddr; };\nstruct m_vm { struct m_slot s[M_SLOTS]; int nv; int ids[M_MAXV]; };\nstruct m_fd { int kind, vm, id; struct kvm_run *run; size_t runlen; uint64_t pc; uint8_t acc; int pend; };\nstatic struct m_fd m_fds[M_FDS];\nstatic struct m_vm m_vms[4];\nstatic int m_nvm;\nstatic struct { void *a; size_t l; } m_maps[32];\nstatic int m_open_err, m_api = 12, m_vm_err, m_runs, m_opens, m_oflags;\nstatic unsigned m_eintr; /* bit k set: the (k+1)-th KVM_RUN fails with EINTR */\n\nstatic int m_fail(int e) { errno = e; return -1; }\nstatic struct m_fd *m_get(int fd) {\n    int i = fd - 100;\n    return (i < 0 || i >= M_FDS || m_fds[i].kind == K_FREE) ? NULL : &m_fds[i];\n}\nstatic int m_alloc(int kind, int vm, int id) {\n    for (int i = 0; i < M_FDS; i++)\n        if (m_fds[i].kind == K_FREE) {\n            memset(&m_fds[i], 0, sizeof m_fds[i]);\n            m_fds[i].kind = kind; m_fds[i].vm = vm; m_fds[i].id = id;\n            return 100 + i;\n        }\n    return -1;\n}\nstatic int m_nopen(void) { int n = 0; for (int i = 0; i < M_FDS; i++) n += m_fds[i].kind != K_FREE; return n; }\nstatic int m_nmaps(void) { int n = 0; for (int i = 0; i < 32; i++) n += m_maps[i].a != NULL; return n; }\nstatic long m_cap(unsigned long c) {\n    switch (c) {\n    case KVM_CAP_USER_MEMORY: case KVM_CAP_IMMEDIATE_EXIT: case KVM_CAP_MP_STATE:\n    case KVM_CAP_IOEVENTFD: case KVM_CAP_IRQFD: return 1;\n    case KVM_CAP_NR_VCPUS: return 4;\n    case KVM_CAP_MAX_VCPUS: return M_MAXV;\n    case KVM_CAP_NR_MEMSLOTS: return M_SLOTS;\n    default: return 0;\n    }\n}\nstatic int m_gread(struct m_vm *v, uint64_t gpa, uint8_t *out, int n) {\n    for (int k = 0; k < n; k++) {\n        int ok = 0;\n        for (int i = 0; i < M_SLOTS && !ok; i++) {\n            struct m_slot *s = &v->s[i];\n            if (s->used && gpa + k >= s->gpa && gpa + k < s->gpa + s->size) {\n                out[k] = ((uint8_t *)(uintptr_t)s->uaddr)[gpa + k - s->gpa];\n                ok = 1;\n            }\n        }\n        if (!ok) return -1;\n    }\n    return 0;\n}\n/* the toy guest: opcode lengths; this is NOT machine code, it is the lab''s own tiny instruction set */\nstatic int m_oplen(int op) {\n    switch (op) {\n    case 0x00: case 0xFF: return 1;\n    case 0x01: return 4;  /* OUT port,imm8 */\n    case 0x02: return 3;  /* IN port -> acc */\n    case 0x03: return 6;  /* MMIO write addr32,imm8 */\n    case 0x04: return 5;  /* MMIO read addr32 -> acc */\n    case 0x05: return 3;  /* OUT port,acc */\n    case 0x06: return 2;  /* acc += imm8 */\n    default: return 0;\n    }\n}\nstatic int m_run(struct m_fd *f) {\n    struct m_vm *v = &m_vms[f->vm];\n    struct kvm_run *r = f->run;\n    if (!r) return m_fail(EINVAL);\n    uint8_t *pio = (uint8_t *)r + PG;\n    m_runs++;\n    if ((m_runs <= 31 && ((m_eintr >> (m_runs - 1)) & 1)) || r->immediate_exit) {\n        r->exit_reason = KVM_EXIT_INTR;\n        return m_fail(EINTR);\n    }\n    if (f->pend == 1) f->acc = pio[0];\n    if (f->pend == 2) f->acc = r->mmio.data[0];\n    f->pend = 0;\n    for (;;) {\n        uint8_t b[8];\n        int n;\n        if (m_gread(v, f->pc, b, 1)) { r->exit_reason = KVM_EXIT_FAIL_ENTRY; r->fail_entry.hardware_entry_failure_reason = 0x1000; r->fail_entry.cpu = 0; return 0; }\n        n = m_oplen(b[0]);\n        if (n == 0) {\n            r->exit_reason = KVM_EXIT_INTERNAL_ERROR;\n            r->internal.suberror = KVM_INTERNAL_ERROR_EMULATION;\n            r->internal.ndata = 0;\n            return 0;\n        }\n        if (m_gread(v, f->pc, b, n)) { r->exit_reason = KVM_EXIT_FAIL_ENTRY; r->fail_entry.hardware_entry_failure_reason = 0x1000; r->fail_entry.cpu = 0; return 0; }\n        f->pc += n;\n        switch (b[0]) {\n        case 0x00: r->exit_reason = KVM_EXIT_HLT; return 0;\n        case 0xFF: r->exit_reason = KVM_EXIT_SHUTDOWN; return 0;\n        case 0x06: f->acc = (uint8_t)(f->acc + b[1]); break;\n        case 0x01: case 0x05:\n            if (f->runlen < 2 * PG) return m_fail(EFAULT);\n            r->exit_reason = KVM_EXIT_IO;\n            r->io.direction = KVM_EXIT_IO_OUT; r->io.size = 1; r->io.count = 1;\n            r->io.port = (uint16_t)(b[1] | b[2] << 8); r->io.data_offset = PG;\n            pio[0] = b[0] == 0x01 ? b[3] : f->acc;\n            return 0;\n        case 0x02:\n            if (f->runlen < 2 * PG) return m_fail(EFAULT);\n            r->exit_reason = KVM_EXIT_IO;\n            r->io.direction = KVM_EXIT_IO_IN; r->io.size = 1; r->io.count = 1;\n            r->io.port = (uint16_t)(b[1] | b[2] << 8); r->io.data_offset = PG;\n            pio[0] = 0; f->pend = 1;\n            return 0;\n        case 0x03: case 0x04:\n            r->exit_reason = KVM_EXIT_MMIO;\n            r->mmio.phys_addr = (uint32_t)b[1] | (uint32_t)b[2] << 8 | (uint32_t)b[3] << 16 | (uint32_t)b[4] << 24;\n            memset(r->mmio.data, 0, 8);\n            r->mmio.len = 1;\n            if (b[0] == 0x03) { r->mmio.is_write = 1; r->mmio.data[0] = b[5]; }\n            else { r->mmio.is_write = 0; f->pend = 2; }\n            return 0;\n        }\n    }\n}\nstatic int m_set_region(struct m_fd *f, struct kvm_userspace_memory_region *m) {\n    struct m_vm *v = &m_vms[f->vm];\n    unsigned slot = m->slot & 0xffff;\n    if (m->flags & ~(KVM_MEM_LOG_DIRTY_PAGES | KVM_MEM_READONLY)) return m_fail(EINVAL);\n    if ((m->memory_size & (PG - 1)) || (m->guest_phys_addr & (PG - 1)) || (m->userspace_addr & (PG - 1))) return m_fail(EINVAL);\n    if ((m->slot >> 16) != 0 || slot >= M_SLOTS) return m_fail(EINVAL);\n    if (m->guest_phys_addr + m->memory_size < m->guest_phys_addr) return m_fail(EINVAL);\n    struct m_slot *s = &v->s[slot];\n    if (m->memory_size == 0) {\n        if (!s->used) return m_fail(EINVAL);\n        s->used = 0;\n        return 0;\n    }\n    if (s->used && (m->userspace_addr != s->uaddr || m->memory_size != s->size)) return m_fail(EINVAL);\n    for (int i = 0; i < M_SLOTS; i++)\n        if (i != (int)slot && v->s[i].used && m->guest_phys_addr < v->s[i].gpa + v->s[i].size &&\n            v->s[i].gpa < m->guest_phys_addr + m->memory_size)\n            return m_fail(EEXIST);\n    s->used = 1; s->gpa = m->guest_phys_addr; s->size = m->memory_size; s->uaddr = m->userspace_addr;\n    return 0;\n}\nint __wrap_open(const char *path, int flags, ...) {\n    if (strcmp(path, \"/dev/kvm\") == 0) {\n        m_opens++; m_oflags = flags;\n        if (m_open_err) return m_fail(m_open_err);\n        int fd = m_alloc(K_SYS, 0, 0);\n        return fd < 0 ? m_fail(EMFILE) : fd;\n    }\n    va_list ap; va_start(ap, flags);\n    int mode = (flags & O_CREAT) ? va_arg(ap, int) : 0;\n    va_end(ap);\n    return __real_open(path, flags, mode);\n}\nint __wrap_close(int fd) {\n    struct m_fd *f = m_get(fd);\n    if (!f) return __real_close(fd);\n    f->kind = K_FREE;\n    return 0;\n}\nint __wrap_ioctl(int fd, unsigned long req, ...) {\n    va_list ap; va_start(ap, req);\n    unsigned long arg = va_arg(ap, unsigned long);\n    va_end(ap);\n    struct m_fd *f = m_get(fd);\n    if (!f) return m_fail(EBADF);\n    if (f->kind == K_SYS) {\n        if (req == KVM_GET_API_VERSION) return (unsigned)arg ? m_fail(EINVAL) : m_api;\n        if (req == KVM_CHECK_EXTENSION) return (int)m_cap((unsigned)arg);\n        if (req == KVM_GET_VCPU_MMAP_SIZE) return (unsigned)arg ? m_fail(EINVAL) : (int)(3 * PG);\n        if (req == KVM_CREATE_VM) {\n            if (m_vm_err) return m_fail(m_vm_err);\n            if ((unsigned)arg != 0 || m_nvm >= 4) return m_fail(EINVAL);\n            int nfd = m_alloc(K_VM, m_nvm, 0);\n            if (nfd < 0) return m_fail(EMFILE);\n            m_nvm++;\n            return nfd;\n        }\n    } else if (f->kind == K_VM) {\n        struct m_vm *v = &m_vms[f->vm];\n        if (req == KVM_CHECK_EXTENSION) return (int)m_cap((unsigned)arg);\n        if (req == KVM_CREATE_VCPU) {\n            if (v->nv >= M_MAXV) return m_fail(EINVAL);\n            for (int i = 0; i < v->nv; i++) if (v->ids[i] == (int)(unsigned)arg) return m_fail(EEXIST);\n            int nfd = m_alloc(K_VCPU, f->vm, (int)(unsigned)arg);\n            if (nfd < 0) return m_fail(EMFILE);\n            v->ids[v->nv++] = (int)(unsigned)arg;\n            return nfd;\n        }\n        if (req == KVM_SET_USER_MEMORY_REGION) {\n            if (arg == 0) return m_fail(EFAULT);\n            return m_set_region(f, (struct kvm_userspace_memory_region *)arg);\n        }\n    } else if (f->kind == K_VCPU) {\n        if (req == KVM_RUN) return (unsigned)arg ? m_fail(EINVAL) : m_run(f);\n    }\n    return m_fail(ENOTTY);\n}\nvoid *__wrap_mmap(void *addr, size_t len, int prot, int flags, int fd, off_t off) {\n    struct m_fd *f = (flags & MAP_ANONYMOUS) ? NULL : m_get(fd);\n    if (f && f->kind != K_VCPU) { errno = ENODEV; return MAP_FAILED; }\n    if (f && (off != 0 || len == 0 || len > 3 * PG)) { errno = EINVAL; return MAP_FAILED; }\n    if (!f && (flags & MAP_ANONYMOUS) == 0) return __real_mmap(addr, len, prot, flags, fd, off);\n    void *p = __real_mmap(f ? NULL : addr, f ? 3 * PG : len, f ? PROT_READ | PROT_WRITE : prot,\n                          f ? MAP_SHARED | MAP_ANONYMOUS : flags, f ? -1 : fd, f ? 0 : off);\n    if (p == MAP_FAILED) return p;\n    for (int i = 0; i < 32; i++)\n        if (!m_maps[i].a) { m_maps[i].a = p; m_maps[i].l = len; break; }\n    if (f) { f->run = p; f->runlen = len; }\n    return p;\n}\nint __wrap_munmap(void *addr, size_t len) {\n    int r = __real_munmap(addr, len);\n    if (r == 0)\n        for (int i = 0; i < 32; i++)\n            if (m_maps[i].a == addr) {\n                m_maps[i].a = NULL;\n                for (int k = 0; k < M_FDS; k++) if (m_fds[k].run == addr) m_fds[k].run = NULL;\n                break;\n            }\n    return r;\n}\n\n/* ---- helpers of the driver ---- */\nstatic void m_reset(void) {\n    memset(m_fds, 0, sizeof m_fds); memset(m_vms, 0, sizeof m_vms); memset(m_maps, 0, sizeof m_maps);\n    m_nvm = 0; m_open_err = 0; m_api = 12; m_vm_err = 0; m_runs = 0; m_opens = 0; m_oflags = 0; m_eintr = 0;\n}\nstatic const char *m_en(int e) {\n    switch (e) {\n    case ENOENT: return \"ENOENT\"; case EACCES: return \"EACCES\"; case EINVAL: return \"EINVAL\";\n    case EEXIST: return \"EEXIST\"; case EBADF: return \"EBADF\"; case EINTR: return \"EINTR\";\n    case EMFILE: return \"EMFILE\"; case ENOMEM: return \"ENOMEM\"; case EPROTO: return \"EPROTO\";\n    case E2BIG: return \"E2BIG\"; case EIO: return \"EIO\"; case ENOTTY: return \"ENOTTY\";\n    case EFAULT: return \"EFAULT\"; case ENODEV: return \"ENODEV\"; case EPERM: return \"EPERM\";\n    }\n    return \"E?\";\n}\nstatic void m_pr(const char *label, long r) {\n    if (r < 0 && r > -4096) printf(\"%s: -%s\\n\", label, m_en((int)-r));\n    else printf(\"%s: %ld\\n\", label, r);\n}\n/* print the result of a raw ioctl/mmap-like call that reports errors through errno */\nstatic void m_pre(const char *label, long r) {\n    int e = errno;\n    if (r < 0) printf(\"%s: -%s\\n\", label, m_en(e));\n    else printf(\"%s: %ld\\n\", label, r);\n}\nstatic void m_leaks(void) { printf(\"leaks: fds=%d maps=%d\\n\", m_nopen(), m_nmaps()); }\nstatic const char *m_kind(int fd) {\n    struct m_fd *f = m_get(fd);\n    return !f ? \"none\" : f->kind == K_SYS ? \"system\" : f->kind == K_VM ? \"vm\" : \"vcpu\";\n}\n/* driver-side setup of a VM with the guest program at guest address 0 and one vCPU mapped for KVM_RUN */\nstatic uint8_t *m_boot(const uint8_t *prog, int len, int *vcpu, struct kvm_run **run) {\n    int kvm = open(\"/dev/kvm\", O_RDWR | O_CLOEXEC);\n    int vm = ioctl(kvm, KVM_CREATE_VM, 0);\n    uint8_t *mem = mmap(NULL, PG, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);\n    memcpy(mem, prog, len);\n    struct kvm_userspace_memory_region r = { .slot = 0, .guest_phys_addr = 0, .memory_size = PG, .userspace_addr = (uintptr_t)mem };\n    ioctl(vm, KVM_SET_USER_MEMORY_REGION, &r);\n    *vcpu = ioctl(vm, KVM_CREATE_VCPU, 0);\n    *run = mmap(NULL, 3 * PG, PROT_READ | PROT_WRITE, MAP_SHARED, *vcpu, 0);\n    return mem;\n}\n\n\nstatic void show(int slot) {\n    struct m_slot *s = &m_vms[0].s[slot];\n    if (s->used) printf(\"slot %d: gpa=0x%llx size=%llu\\n\", slot, (unsigned long long)s->gpa, (unsigned long long)s->size);\n    else printf(\"slot %d: empty\\n\", slot);\n}\nint main(void) {\n    static char big[5000];\n    memset(big, ''z'', sizeof big);\n    void *h0 = NULL, *h1 = NULL;\n    m_reset();\n    int kvm = open(\"/dev/kvm\", O_RDWR | O_CLOEXEC);\n    int vm = ioctl(kvm, KVM_CREATE_VM, 0);\n    m_pr(\"slot 0\", guest_mem(vm, 0, 0, 5000, \"ABC\", 3, &h0));\n    show(0);\n    uint8_t b[3];\n    m_gread(&m_vms[0], 0, b, 3);\n    printf(\"guest sees: %c%c%c\\n\", b[0], b[1], b[2]);\n    printf(\"maps: %d\\n\", m_nmaps());\n    m_pr(\"unaligned address\", guest_mem(vm, 1, 0x4800, 4096, \"x\", 1, &h1));\n    printf(\"maps: %d\\n\", m_nmaps());\n    m_pr(\"overlap\", guest_mem(vm, 1, 0x1000, 4096, \"x\", 1, &h1));\n    printf(\"maps: %d\\n\", m_nmaps());\n    m_pr(\"image too big\", guest_mem(vm, 1, 0x10000, 4096, big, 5000, &h1));\n    printf(\"maps: %d\\n\", m_nmaps());\n    m_pr(\"slot too high\", guest_mem(vm, 40, 0x10000, 4096, \"x\", 1, &h1));\n    printf(\"maps: %d\\n\", m_nmaps());\n    m_pr(\"slot 1\", guest_mem(vm, 1, 0x10000, 1, \"Q\", 1, &h1));\n    show(1);\n    printf(\"maps: %d\\n\", m_nmaps());\n    munmap(h0, 8192); munmap(h1, 4096);\n    close(vm); close(kvm);\n    m_leaks();\n    return 0;\n}\n", "expected": ["slot 0: 0", "slot 0: gpa=0x0 size=8192", "guest sees: ABC", "maps: 1", "unaligned address: -EINVAL", "maps: 1", "overlap: -EEXIST", "maps: 1", "image too big: -E2BIG", "maps: 1", "slot too high: -EINVAL", "maps: 1", "slot 1: 0", "slot 1: gpa=0x10000 size=4096", "maps: 2", "leaks: fds=0 maps=0"], "flags": "-std=gnu11 -O1 -Wall -Wl,--wrap=open,--wrap=ioctl,--wrap=close,--wrap=mmap,--wrap=munmap"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 28, 'la28-run-loop', 5, 'c', 'Цикл KVM_RUN и последовательный порт', 'Сердце любого VMM — цикл: вызвать KVM_RUN, разобрать причину выхода, обработать, повторить. Напишите int run_serial(int vcpu, struct kvm_run *run, char *out, size_t cap). Структура struct kvm_run уже отображена драйвером (аргумент run, это mmap дескриптора vCPU размером KVM_GET_VCPU_MMAP_SIZE). KVM_RUN возвращает 0, когда гость вышел, и причину надо читать в run->exit_reason; -1 с EINTR значит «прервал сигнал, вызовите снова». Обрабатывайте так: EINTR — повторить вызов; другая ошибка KVM_RUN — вернуть -errno; KVM_EXIT_IO с direction KVM_EXIT_IO_OUT на порту 0x3f8 — «последовательный порт»: добавить size*count байт, лежащих по адресу (char *)run + run->io.data_offset, в out (в out помещается не больше cap-1 символов, лишние отбрасывайте, но гостя продолжайте исполнять); вывод в другие порты игнорируйте; ввод (KVM_EXIT_IO_IN) из любого порта отвечайте байтами 0xFF (size*count байт по тому же data_offset); KVM_EXIT_HLT завершает работу: поставьте в конце out нулевой байт и верните число сохранённых символов; любой другой выход — вернуть -EIO. Гость в модели не настоящий машинный код, а игрушечная программа (лабораторное упрощение): запись в память гостя, начиная с адреса 0. Команды: 0x00 останов (выход KVM_EXIT_HLT); 0x01 pL pH v вывод байта v в порт pH:pL (KVM_EXIT_IO, direction OUT, size 1, count 1, данные лежат по run + data_offset); 0x02 pL pH ввод из порта (KVM_EXIT_IO, direction IN: ответ положите по тому же data_offset до следующего KVM_RUN); 0x05 pL pH вывод в порт накопителя acc; 0x06 v прибавить v к acc; 0xFF KVM_EXIT_SHUTDOWN; неизвестный код даёт KVM_EXIT_INTERNAL_ERROR. Устройства /dev/kvm в песочнице нет: драйвер подставляет МОДЕЛЬ ядра (лабораторное упрощение, константы и структуры настоящие, из linux/kvm.h; поведение модели описано в условии). Пишите обычный код с open, ioctl, close, mmap, как для настоящего устройства.', '#include <errno.h>
#include <fcntl.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/kvm.h>

int run_serial(int vcpu, struct kvm_run *run, char *out, size_t cap) {
    // цикл KVM_RUN и разбор run->exit_reason
    return -1;
}
', 'Цикл for (;;) { r = ioctl(vcpu, KVM_RUN, 0); ... }. Данные порта лежат внутри отображения run, а не в структуре io.', '{"driver": "/*__DRIVER__*/\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <stdint.h>\n#include <stdarg.h>\n#include <errno.h>\n#include <fcntl.h>\n#include <unistd.h>\n#include <sys/mman.h>\n#include <sys/ioctl.h>\n#include <linux/kvm.h>\n\n/* ---- LAB MODEL of /dev/kvm: a fake kernel behind the linker''s --wrap (the sandbox has no /dev/kvm) ---- */\nextern int __real_open(const char *, int, ...);\nextern int __real_close(int);\nextern void *__real_mmap(void *, size_t, int, int, int, off_t);\nextern int __real_munmap(void *, size_t);\n\n#define PG 4096UL\n#define M_FDS 16\n#define M_SLOTS 32\n#define M_MAXV 8\nenum { K_FREE, K_SYS, K_VM, K_VCPU };\nstruct m_slot { int used; uint64_t gpa, size, uaddr; };\nstruct m_vm { struct m_slot s[M_SLOTS]; int nv; int ids[M_MAXV]; };\nstruct m_fd { int kind, vm, id; struct kvm_run *run; size_t runlen; uint64_t pc; uint8_t acc; int pend; };\nstatic struct m_fd m_fds[M_FDS];\nstatic struct m_vm m_vms[4];\nstatic int m_nvm;\nstatic struct { void *a; size_t l; } m_maps[32];\nstatic int m_open_err, m_api = 12, m_vm_err, m_runs, m_opens, m_oflags;\nstatic unsigned m_eintr; /* bit k set: the (k+1)-th KVM_RUN fails with EINTR */\n\nstatic int m_fail(int e) { errno = e; return -1; }\nstatic struct m_fd *m_get(int fd) {\n    int i = fd - 100;\n    return (i < 0 || i >= M_FDS || m_fds[i].kind == K_FREE) ? NULL : &m_fds[i];\n}\nstatic int m_alloc(int kind, int vm, int id) {\n    for (int i = 0; i < M_FDS; i++)\n        if (m_fds[i].kind == K_FREE) {\n            memset(&m_fds[i], 0, sizeof m_fds[i]);\n            m_fds[i].kind = kind; m_fds[i].vm = vm; m_fds[i].id = id;\n            return 100 + i;\n        }\n    return -1;\n}\nstatic int m_nopen(void) { int n = 0; for (int i = 0; i < M_FDS; i++) n += m_fds[i].kind != K_FREE; return n; }\nstatic int m_nmaps(void) { int n = 0; for (int i = 0; i < 32; i++) n += m_maps[i].a != NULL; return n; }\nstatic long m_cap(unsigned long c) {\n    switch (c) {\n    case KVM_CAP_USER_MEMORY: case KVM_CAP_IMMEDIATE_EXIT: case KVM_CAP_MP_STATE:\n    case KVM_CAP_IOEVENTFD: case KVM_CAP_IRQFD: return 1;\n    case KVM_CAP_NR_VCPUS: return 4;\n    case KVM_CAP_MAX_VCPUS: return M_MAXV;\n    case KVM_CAP_NR_MEMSLOTS: return M_SLOTS;\n    default: return 0;\n    }\n}\nstatic int m_gread(struct m_vm *v, uint64_t gpa, uint8_t *out, int n) {\n    for (int k = 0; k < n; k++) {\n        int ok = 0;\n        for (int i = 0; i < M_SLOTS && !ok; i++) {\n            struct m_slot *s = &v->s[i];\n            if (s->used && gpa + k >= s->gpa && gpa + k < s->gpa + s->size) {\n                out[k] = ((uint8_t *)(uintptr_t)s->uaddr)[gpa + k - s->gpa];\n                ok = 1;\n            }\n        }\n        if (!ok) return -1;\n    }\n    return 0;\n}\n/* the toy guest: opcode lengths; this is NOT machine code, it is the lab''s own tiny instruction set */\nstatic int m_oplen(int op) {\n    switch (op) {\n    case 0x00: case 0xFF: return 1;\n    case 0x01: return 4;  /* OUT port,imm8 */\n    case 0x02: return 3;  /* IN port -> acc */\n    case 0x03: return 6;  /* MMIO write addr32,imm8 */\n    case 0x04: return 5;  /* MMIO read addr32 -> acc */\n    case 0x05: return 3;  /* OUT port,acc */\n    case 0x06: return 2;  /* acc += imm8 */\n    default: return 0;\n    }\n}\nstatic int m_run(struct m_fd *f) {\n    struct m_vm *v = &m_vms[f->vm];\n    struct kvm_run *r = f->run;\n    if (!r) return m_fail(EINVAL);\n    uint8_t *pio = (uint8_t *)r + PG;\n    m_runs++;\n    if ((m_runs <= 31 && ((m_eintr >> (m_runs - 1)) & 1)) || r->immediate_exit) {\n        r->exit_reason = KVM_EXIT_INTR;\n        return m_fail(EINTR);\n    }\n    if (f->pend == 1) f->acc = pio[0];\n    if (f->pend == 2) f->acc = r->mmio.data[0];\n    f->pend = 0;\n    for (;;) {\n        uint8_t b[8];\n        int n;\n        if (m_gread(v, f->pc, b, 1)) { r->exit_reason = KVM_EXIT_FAIL_ENTRY; r->fail_entry.hardware_entry_failure_reason = 0x1000; r->fail_entry.cpu = 0; return 0; }\n        n = m_oplen(b[0]);\n        if (n == 0) {\n            r->exit_reason = KVM_EXIT_INTERNAL_ERROR;\n            r->internal.suberror = KVM_INTERNAL_ERROR_EMULATION;\n            r->internal.ndata = 0;\n            return 0;\n        }\n        if (m_gread(v, f->pc, b, n)) { r->exit_reason = KVM_EXIT_FAIL_ENTRY; r->fail_entry.hardware_entry_failure_reason = 0x1000; r->fail_entry.cpu = 0; return 0; }\n        f->pc += n;\n        switch (b[0]) {\n        case 0x00: r->exit_reason = KVM_EXIT_HLT; return 0;\n        case 0xFF: r->exit_reason = KVM_EXIT_SHUTDOWN; return 0;\n        case 0x06: f->acc = (uint8_t)(f->acc + b[1]); break;\n        case 0x01: case 0x05:\n            if (f->runlen < 2 * PG) return m_fail(EFAULT);\n            r->exit_reason = KVM_EXIT_IO;\n            r->io.direction = KVM_EXIT_IO_OUT; r->io.size = 1; r->io.count = 1;\n            r->io.port = (uint16_t)(b[1] | b[2] << 8); r->io.data_offset = PG;\n            pio[0] = b[0] == 0x01 ? b[3] : f->acc;\n            return 0;\n        case 0x02:\n            if (f->runlen < 2 * PG) return m_fail(EFAULT);\n            r->exit_reason = KVM_EXIT_IO;\n            r->io.direction = KVM_EXIT_IO_IN; r->io.size = 1; r->io.count = 1;\n            r->io.port = (uint16_t)(b[1] | b[2] << 8); r->io.data_offset = PG;\n            pio[0] = 0; f->pend = 1;\n            return 0;\n        case 0x03: case 0x04:\n            r->exit_reason = KVM_EXIT_MMIO;\n            r->mmio.phys_addr = (uint32_t)b[1] | (uint32_t)b[2] << 8 | (uint32_t)b[3] << 16 | (uint32_t)b[4] << 24;\n            memset(r->mmio.data, 0, 8);\n            r->mmio.len = 1;\n            if (b[0] == 0x03) { r->mmio.is_write = 1; r->mmio.data[0] = b[5]; }\n            else { r->mmio.is_write = 0; f->pend = 2; }\n            return 0;\n        }\n    }\n}\nstatic int m_set_region(struct m_fd *f, struct kvm_userspace_memory_region *m) {\n    struct m_vm *v = &m_vms[f->vm];\n    unsigned slot = m->slot & 0xffff;\n    if (m->flags & ~(KVM_MEM_LOG_DIRTY_PAGES | KVM_MEM_READONLY)) return m_fail(EINVAL);\n    if ((m->memory_size & (PG - 1)) || (m->guest_phys_addr & (PG - 1)) || (m->userspace_addr & (PG - 1))) return m_fail(EINVAL);\n    if ((m->slot >> 16) != 0 || slot >= M_SLOTS) return m_fail(EINVAL);\n    if (m->guest_phys_addr + m->memory_size < m->guest_phys_addr) return m_fail(EINVAL);\n    struct m_slot *s = &v->s[slot];\n    if (m->memory_size == 0) {\n        if (!s->used) return m_fail(EINVAL);\n        s->used = 0;\n        return 0;\n    }\n    if (s->used && (m->userspace_addr != s->uaddr || m->memory_size != s->size)) return m_fail(EINVAL);\n    for (int i = 0; i < M_SLOTS; i++)\n        if (i != (int)slot && v->s[i].used && m->guest_phys_addr < v->s[i].gpa + v->s[i].size &&\n            v->s[i].gpa < m->guest_phys_addr + m->memory_size)\n            return m_fail(EEXIST);\n    s->used = 1; s->gpa = m->guest_phys_addr; s->size = m->memory_size; s->uaddr = m->userspace_addr;\n    return 0;\n}\nint __wrap_open(const char *path, int flags, ...) {\n    if (strcmp(path, \"/dev/kvm\") == 0) {\n        m_opens++; m_oflags = flags;\n        if (m_open_err) return m_fail(m_open_err);\n        int fd = m_alloc(K_SYS, 0, 0);\n        return fd < 0 ? m_fail(EMFILE) : fd;\n    }\n    va_list ap; va_start(ap, flags);\n    int mode = (flags & O_CREAT) ? va_arg(ap, int) : 0;\n    va_end(ap);\n    return __real_open(path, flags, mode);\n}\nint __wrap_close(int fd) {\n    struct m_fd *f = m_get(fd);\n    if (!f) return __real_close(fd);\n    f->kind = K_FREE;\n    return 0;\n}\nint __wrap_ioctl(int fd, unsigned long req, ...) {\n    va_list ap; va_start(ap, req);\n    unsigned long arg = va_arg(ap, unsigned long);\n    va_end(ap);\n    struct m_fd *f = m_get(fd);\n    if (!f) return m_fail(EBADF);\n    if (f->kind == K_SYS) {\n        if (req == KVM_GET_API_VERSION) return (unsigned)arg ? m_fail(EINVAL) : m_api;\n        if (req == KVM_CHECK_EXTENSION) return (int)m_cap((unsigned)arg);\n        if (req == KVM_GET_VCPU_MMAP_SIZE) return (unsigned)arg ? m_fail(EINVAL) : (int)(3 * PG);\n        if (req == KVM_CREATE_VM) {\n            if (m_vm_err) return m_fail(m_vm_err);\n            if ((unsigned)arg != 0 || m_nvm >= 4) return m_fail(EINVAL);\n            int nfd = m_alloc(K_VM, m_nvm, 0);\n            if (nfd < 0) return m_fail(EMFILE);\n            m_nvm++;\n            return nfd;\n        }\n    } else if (f->kind == K_VM) {\n        struct m_vm *v = &m_vms[f->vm];\n        if (req == KVM_CHECK_EXTENSION) return (int)m_cap((unsigned)arg);\n        if (req == KVM_CREATE_VCPU) {\n            if (v->nv >= M_MAXV) return m_fail(EINVAL);\n            for (int i = 0; i < v->nv; i++) if (v->ids[i] == (int)(unsigned)arg) return m_fail(EEXIST);\n            int nfd = m_alloc(K_VCPU, f->vm, (int)(unsigned)arg);\n            if (nfd < 0) return m_fail(EMFILE);\n            v->ids[v->nv++] = (int)(unsigned)arg;\n            return nfd;\n        }\n        if (req == KVM_SET_USER_MEMORY_REGION) {\n            if (arg == 0) return m_fail(EFAULT);\n            return m_set_region(f, (struct kvm_userspace_memory_region *)arg);\n        }\n    } else if (f->kind == K_VCPU) {\n        if (req == KVM_RUN) return (unsigned)arg ? m_fail(EINVAL) : m_run(f);\n    }\n    return m_fail(ENOTTY);\n}\nvoid *__wrap_mmap(void *addr, size_t len, int prot, int flags, int fd, off_t off) {\n    struct m_fd *f = (flags & MAP_ANONYMOUS) ? NULL : m_get(fd);\n    if (f && f->kind != K_VCPU) { errno = ENODEV; return MAP_FAILED; }\n    if (f && (off != 0 || len == 0 || len > 3 * PG)) { errno = EINVAL; return MAP_FAILED; }\n    if (!f && (flags & MAP_ANONYMOUS) == 0) return __real_mmap(addr, len, prot, flags, fd, off);\n    void *p = __real_mmap(f ? NULL : addr, f ? 3 * PG : len, f ? PROT_READ | PROT_WRITE : prot,\n                          f ? MAP_SHARED | MAP_ANONYMOUS : flags, f ? -1 : fd, f ? 0 : off);\n    if (p == MAP_FAILED) return p;\n    for (int i = 0; i < 32; i++)\n        if (!m_maps[i].a) { m_maps[i].a = p; m_maps[i].l = len; break; }\n    if (f) { f->run = p; f->runlen = len; }\n    return p;\n}\nint __wrap_munmap(void *addr, size_t len) {\n    int r = __real_munmap(addr, len);\n    if (r == 0)\n        for (int i = 0; i < 32; i++)\n            if (m_maps[i].a == addr) {\n                m_maps[i].a = NULL;\n                for (int k = 0; k < M_FDS; k++) if (m_fds[k].run == addr) m_fds[k].run = NULL;\n                break;\n            }\n    return r;\n}\n\n/* ---- helpers of the driver ---- */\nstatic void m_reset(void) {\n    memset(m_fds, 0, sizeof m_fds); memset(m_vms, 0, sizeof m_vms); memset(m_maps, 0, sizeof m_maps);\n    m_nvm = 0; m_open_err = 0; m_api = 12; m_vm_err = 0; m_runs = 0; m_opens = 0; m_oflags = 0; m_eintr = 0;\n}\nstatic const char *m_en(int e) {\n    switch (e) {\n    case ENOENT: return \"ENOENT\"; case EACCES: return \"EACCES\"; case EINVAL: return \"EINVAL\";\n    case EEXIST: return \"EEXIST\"; case EBADF: return \"EBADF\"; case EINTR: return \"EINTR\";\n    case EMFILE: return \"EMFILE\"; case ENOMEM: return \"ENOMEM\"; case EPROTO: return \"EPROTO\";\n    case E2BIG: return \"E2BIG\"; case EIO: return \"EIO\"; case ENOTTY: return \"ENOTTY\";\n    case EFAULT: return \"EFAULT\"; case ENODEV: return \"ENODEV\"; case EPERM: return \"EPERM\";\n    }\n    return \"E?\";\n}\nstatic void m_pr(const char *label, long r) {\n    if (r < 0 && r > -4096) printf(\"%s: -%s\\n\", label, m_en((int)-r));\n    else printf(\"%s: %ld\\n\", label, r);\n}\n/* print the result of a raw ioctl/mmap-like call that reports errors through errno */\nstatic void m_pre(const char *label, long r) {\n    int e = errno;\n    if (r < 0) printf(\"%s: -%s\\n\", label, m_en(e));\n    else printf(\"%s: %ld\\n\", label, r);\n}\nstatic void m_leaks(void) { printf(\"leaks: fds=%d maps=%d\\n\", m_nopen(), m_nmaps()); }\nstatic const char *m_kind(int fd) {\n    struct m_fd *f = m_get(fd);\n    return !f ? \"none\" : f->kind == K_SYS ? \"system\" : f->kind == K_VM ? \"vm\" : \"vcpu\";\n}\n/* driver-side setup of a VM with the guest program at guest address 0 and one vCPU mapped for KVM_RUN */\nstatic uint8_t *m_boot(const uint8_t *prog, int len, int *vcpu, struct kvm_run **run) {\n    int kvm = open(\"/dev/kvm\", O_RDWR | O_CLOEXEC);\n    int vm = ioctl(kvm, KVM_CREATE_VM, 0);\n    uint8_t *mem = mmap(NULL, PG, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);\n    memcpy(mem, prog, len);\n    struct kvm_userspace_memory_region r = { .slot = 0, .guest_phys_addr = 0, .memory_size = PG, .userspace_addr = (uintptr_t)mem };\n    ioctl(vm, KVM_SET_USER_MEMORY_REGION, &r);\n    *vcpu = ioctl(vm, KVM_CREATE_VCPU, 0);\n    *run = mmap(NULL, 3 * PG, PROT_READ | PROT_WRITE, MAP_SHARED, *vcpu, 0);\n    return mem;\n}\n\n\nstatic const uint8_t HI[] = { 0x01, 0xf8, 0x03, ''H'', 0x01, 0xf8, 0x03, ''i'', 0x01, 0xf8, 0x03, ''!'', 0x00 };\n\nstatic void play(const char *label, const uint8_t *prog, int len, size_t cap) {\n    int vcpu; struct kvm_run *run;\n    char out[64];\n    memset(out, ''#'', sizeof out);\n    m_boot(prog, len, &vcpu, &run);\n    long r = run_serial(vcpu, run, out, cap);\n    m_pr(label, r);\n    if (r >= 0) printf(\"output: [%s]\\n\", out);\n}\nint main(void) {\n    m_reset(); play(\"hello\", HI, sizeof HI, 64);\n    m_reset(); m_eintr = 5; play(\"hello with signals\", HI, sizeof HI, 64);\n    printf(\"KVM_RUN calls: %d\\n\", m_runs);\n    static const uint8_t other[] = { 0x01, 0x80, 0x00, ''x'', 0x01, 0xf8, 0x03, ''y'', 0x00 };\n    m_reset(); play(\"other port\", other, sizeof other, 64);\n    static const uint8_t in[] = { 0x02, 0x60, 0x00, 0x06, 0x42, 0x05, 0xf8, 0x03, 0x00 };\n    m_reset(); play(\"port input\", in, sizeof in, 64);\n    m_reset(); play(\"small buffer\", HI, sizeof HI, 3);\n    static const uint8_t bad[] = { 0x01, 0xf8, 0x03, ''a'', 0x77 };\n    m_reset(); play(\"unknown instruction\", bad, sizeof bad, 64);\n    static const uint8_t down[] = { 0xFF };\n    m_reset(); play(\"shutdown\", down, sizeof down, 64);\n    return 0;\n}\n", "expected": ["hello: 3", "output: [Hi!]", "hello with signals: 3", "output: [Hi!]", "KVM_RUN calls: 6", "other port: 1", "output: [y]", "port input: 1", "output: [A]", "small buffer: 2", "output: [Hi]", "unknown instruction: -EIO", "shutdown: -EIO"], "flags": "-std=gnu11 -O1 -Wall -Wl,--wrap=open,--wrap=ioctl,--wrap=close,--wrap=mmap,--wrap=munmap"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 28, 'la28-mmio-device', 6, 'c', 'Устройство в адресах гостя: KVM_EXIT_MMIO', 'Когда гость обращается к гостевому физическому адресу, где нет памяти, KVM возвращает выход KVM_EXIT_MMIO, а устройство «играет» сам VMM. Напишите int run_device(int vcpu, struct kvm_run *run, char *out, size_t cap). Структура struct kvm_run уже отображена драйвером (аргумент run, это mmap дескриптора vCPU размером KVM_GET_VCPU_MMAP_SIZE). KVM_RUN возвращает 0, когда гость вышел, и причину надо читать в run->exit_reason; -1 с EINTR значит «прервал сигнал, вызовите снова». Как и в предыдущей задаче: EINTR повторяет вызов, другая ошибка даёт -errno, вывод в порт 0x3f8 (OUT, байт по адресу (char *)run + run->io.data_offset) добавляется в out (не больше cap-1 символов), остальной вывод в порты игнорируется, KVM_EXIT_HLT завершает работу (нулевой байт в конец out, вернуть число символов), любой другой выход, кроме описанных ниже, даёт -EIO. Новое: выход KVM_EXIT_MMIO. В модели есть устройство-счётчик по адресу 0x10000000: чтение (run->mmio.is_write == 0) возвращает текущее значение счётчика (одним байтом, положите его в run->mmio.data[0]) и увеличивает счётчик на единицу; запись (is_write == 1) устанавливает счётчик в run->mmio.data[0]. Счётчик — один байт, начинается с нуля. Чтение по любому другому адресу отвечайте байтом 0xFF, запись по другому адресу игнорируйте. Длина обращения всегда один байт. Гость в модели не настоящий машинный код, а игрушечная программа (лабораторное упрощение): запись в память гостя, начиная с адреса 0. Команды: 0x00 останов (выход KVM_EXIT_HLT); 0x01 pL pH v вывод байта v в порт pH:pL (KVM_EXIT_IO, direction OUT, size 1, count 1, данные лежат по run + data_offset); 0x02 pL pH ввод из порта (KVM_EXIT_IO, direction IN: ответ положите по тому же data_offset до следующего KVM_RUN); 0x05 pL pH вывод в порт накопителя acc; 0x06 v прибавить v к acc; 0xFF KVM_EXIT_SHUTDOWN; неизвестный код даёт KVM_EXIT_INTERNAL_ERROR. Дополнительно: 0x03 a0 a1 a2 a3 v запись байта v по адресу a3a2a1a0 (KVM_EXIT_MMIO, is_write 1); 0x04 a0 a1 a2 a3 чтение байта по этому адресу в acc (ответ кладёте вы, в run->mmio.data[0], до следующего KVM_RUN). Устройства /dev/kvm в песочнице нет: драйвер подставляет МОДЕЛЬ ядра (лабораторное упрощение, константы и структуры настоящие, из linux/kvm.h; поведение модели описано в условии). Пишите обычный код с open, ioctl, close, mmap, как для настоящего устройства.', '#include <errno.h>
#include <fcntl.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/kvm.h>

int run_device(int vcpu, struct kvm_run *run, char *out, size_t cap) {
    // цикл KVM_RUN: порт 0x3f8, MMIO-счётчик по адресу 0x10000000
    return -1;
}
', 'Состояние устройства (счётчик) хранится в локальной переменной функции. Для чтения заполняйте data[0] до следующего KVM_RUN.', '{"driver": "/*__DRIVER__*/\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <stdint.h>\n#include <stdarg.h>\n#include <errno.h>\n#include <fcntl.h>\n#include <unistd.h>\n#include <sys/mman.h>\n#include <sys/ioctl.h>\n#include <linux/kvm.h>\n\n/* ---- LAB MODEL of /dev/kvm: a fake kernel behind the linker''s --wrap (the sandbox has no /dev/kvm) ---- */\nextern int __real_open(const char *, int, ...);\nextern int __real_close(int);\nextern void *__real_mmap(void *, size_t, int, int, int, off_t);\nextern int __real_munmap(void *, size_t);\n\n#define PG 4096UL\n#define M_FDS 16\n#define M_SLOTS 32\n#define M_MAXV 8\nenum { K_FREE, K_SYS, K_VM, K_VCPU };\nstruct m_slot { int used; uint64_t gpa, size, uaddr; };\nstruct m_vm { struct m_slot s[M_SLOTS]; int nv; int ids[M_MAXV]; };\nstruct m_fd { int kind, vm, id; struct kvm_run *run; size_t runlen; uint64_t pc; uint8_t acc; int pend; };\nstatic struct m_fd m_fds[M_FDS];\nstatic struct m_vm m_vms[4];\nstatic int m_nvm;\nstatic struct { void *a; size_t l; } m_maps[32];\nstatic int m_open_err, m_api = 12, m_vm_err, m_runs, m_opens, m_oflags;\nstatic unsigned m_eintr; /* bit k set: the (k+1)-th KVM_RUN fails with EINTR */\n\nstatic int m_fail(int e) { errno = e; return -1; }\nstatic struct m_fd *m_get(int fd) {\n    int i = fd - 100;\n    return (i < 0 || i >= M_FDS || m_fds[i].kind == K_FREE) ? NULL : &m_fds[i];\n}\nstatic int m_alloc(int kind, int vm, int id) {\n    for (int i = 0; i < M_FDS; i++)\n        if (m_fds[i].kind == K_FREE) {\n            memset(&m_fds[i], 0, sizeof m_fds[i]);\n            m_fds[i].kind = kind; m_fds[i].vm = vm; m_fds[i].id = id;\n            return 100 + i;\n        }\n    return -1;\n}\nstatic int m_nopen(void) { int n = 0; for (int i = 0; i < M_FDS; i++) n += m_fds[i].kind != K_FREE; return n; }\nstatic int m_nmaps(void) { int n = 0; for (int i = 0; i < 32; i++) n += m_maps[i].a != NULL; return n; }\nstatic long m_cap(unsigned long c) {\n    switch (c) {\n    case KVM_CAP_USER_MEMORY: case KVM_CAP_IMMEDIATE_EXIT: case KVM_CAP_MP_STATE:\n    case KVM_CAP_IOEVENTFD: case KVM_CAP_IRQFD: return 1;\n    case KVM_CAP_NR_VCPUS: return 4;\n    case KVM_CAP_MAX_VCPUS: return M_MAXV;\n    case KVM_CAP_NR_MEMSLOTS: return M_SLOTS;\n    default: return 0;\n    }\n}\nstatic int m_gread(struct m_vm *v, uint64_t gpa, uint8_t *out, int n) {\n    for (int k = 0; k < n; k++) {\n        int ok = 0;\n        for (int i = 0; i < M_SLOTS && !ok; i++) {\n            struct m_slot *s = &v->s[i];\n            if (s->used && gpa + k >= s->gpa && gpa + k < s->gpa + s->size) {\n                out[k] = ((uint8_t *)(uintptr_t)s->uaddr)[gpa + k - s->gpa];\n                ok = 1;\n            }\n        }\n        if (!ok) return -1;\n    }\n    return 0;\n}\n/* the toy guest: opcode lengths; this is NOT machine code, it is the lab''s own tiny instruction set */\nstatic int m_oplen(int op) {\n    switch (op) {\n    case 0x00: case 0xFF: return 1;\n    case 0x01: return 4;  /* OUT port,imm8 */\n    case 0x02: return 3;  /* IN port -> acc */\n    case 0x03: return 6;  /* MMIO write addr32,imm8 */\n    case 0x04: return 5;  /* MMIO read addr32 -> acc */\n    case 0x05: return 3;  /* OUT port,acc */\n    case 0x06: return 2;  /* acc += imm8 */\n    default: return 0;\n    }\n}\nstatic int m_run(struct m_fd *f) {\n    struct m_vm *v = &m_vms[f->vm];\n    struct kvm_run *r = f->run;\n    if (!r) return m_fail(EINVAL);\n    uint8_t *pio = (uint8_t *)r + PG;\n    m_runs++;\n    if ((m_runs <= 31 && ((m_eintr >> (m_runs - 1)) & 1)) || r->immediate_exit) {\n        r->exit_reason = KVM_EXIT_INTR;\n        return m_fail(EINTR);\n    }\n    if (f->pend == 1) f->acc = pio[0];\n    if (f->pend == 2) f->acc = r->mmio.data[0];\n    f->pend = 0;\n    for (;;) {\n        uint8_t b[8];\n        int n;\n        if (m_gread(v, f->pc, b, 1)) { r->exit_reason = KVM_EXIT_FAIL_ENTRY; r->fail_entry.hardware_entry_failure_reason = 0x1000; r->fail_entry.cpu = 0; return 0; }\n        n = m_oplen(b[0]);\n        if (n == 0) {\n            r->exit_reason = KVM_EXIT_INTERNAL_ERROR;\n            r->internal.suberror = KVM_INTERNAL_ERROR_EMULATION;\n            r->internal.ndata = 0;\n            return 0;\n        }\n        if (m_gread(v, f->pc, b, n)) { r->exit_reason = KVM_EXIT_FAIL_ENTRY; r->fail_entry.hardware_entry_failure_reason = 0x1000; r->fail_entry.cpu = 0; return 0; }\n        f->pc += n;\n        switch (b[0]) {\n        case 0x00: r->exit_reason = KVM_EXIT_HLT; return 0;\n        case 0xFF: r->exit_reason = KVM_EXIT_SHUTDOWN; return 0;\n        case 0x06: f->acc = (uint8_t)(f->acc + b[1]); break;\n        case 0x01: case 0x05:\n            if (f->runlen < 2 * PG) return m_fail(EFAULT);\n            r->exit_reason = KVM_EXIT_IO;\n            r->io.direction = KVM_EXIT_IO_OUT; r->io.size = 1; r->io.count = 1;\n            r->io.port = (uint16_t)(b[1] | b[2] << 8); r->io.data_offset = PG;\n            pio[0] = b[0] == 0x01 ? b[3] : f->acc;\n            return 0;\n        case 0x02:\n            if (f->runlen < 2 * PG) return m_fail(EFAULT);\n            r->exit_reason = KVM_EXIT_IO;\n            r->io.direction = KVM_EXIT_IO_IN; r->io.size = 1; r->io.count = 1;\n            r->io.port = (uint16_t)(b[1] | b[2] << 8); r->io.data_offset = PG;\n            pio[0] = 0; f->pend = 1;\n            return 0;\n        case 0x03: case 0x04:\n            r->exit_reason = KVM_EXIT_MMIO;\n            r->mmio.phys_addr = (uint32_t)b[1] | (uint32_t)b[2] << 8 | (uint32_t)b[3] << 16 | (uint32_t)b[4] << 24;\n            memset(r->mmio.data, 0, 8);\n            r->mmio.len = 1;\n            if (b[0] == 0x03) { r->mmio.is_write = 1; r->mmio.data[0] = b[5]; }\n            else { r->mmio.is_write = 0; f->pend = 2; }\n            return 0;\n        }\n    }\n}\nstatic int m_set_region(struct m_fd *f, struct kvm_userspace_memory_region *m) {\n    struct m_vm *v = &m_vms[f->vm];\n    unsigned slot = m->slot & 0xffff;\n    if (m->flags & ~(KVM_MEM_LOG_DIRTY_PAGES | KVM_MEM_READONLY)) return m_fail(EINVAL);\n    if ((m->memory_size & (PG - 1)) || (m->guest_phys_addr & (PG - 1)) || (m->userspace_addr & (PG - 1))) return m_fail(EINVAL);\n    if ((m->slot >> 16) != 0 || slot >= M_SLOTS) return m_fail(EINVAL);\n    if (m->guest_phys_addr + m->memory_size < m->guest_phys_addr) return m_fail(EINVAL);\n    struct m_slot *s = &v->s[slot];\n    if (m->memory_size == 0) {\n        if (!s->used) return m_fail(EINVAL);\n        s->used = 0;\n        return 0;\n    }\n    if (s->used && (m->userspace_addr != s->uaddr || m->memory_size != s->size)) return m_fail(EINVAL);\n    for (int i = 0; i < M_SLOTS; i++)\n        if (i != (int)slot && v->s[i].used && m->guest_phys_addr < v->s[i].gpa + v->s[i].size &&\n            v->s[i].gpa < m->guest_phys_addr + m->memory_size)\n            return m_fail(EEXIST);\n    s->used = 1; s->gpa = m->guest_phys_addr; s->size = m->memory_size; s->uaddr = m->userspace_addr;\n    return 0;\n}\nint __wrap_open(const char *path, int flags, ...) {\n    if (strcmp(path, \"/dev/kvm\") == 0) {\n        m_opens++; m_oflags = flags;\n        if (m_open_err) return m_fail(m_open_err);\n        int fd = m_alloc(K_SYS, 0, 0);\n        return fd < 0 ? m_fail(EMFILE) : fd;\n    }\n    va_list ap; va_start(ap, flags);\n    int mode = (flags & O_CREAT) ? va_arg(ap, int) : 0;\n    va_end(ap);\n    return __real_open(path, flags, mode);\n}\nint __wrap_close(int fd) {\n    struct m_fd *f = m_get(fd);\n    if (!f) return __real_close(fd);\n    f->kind = K_FREE;\n    return 0;\n}\nint __wrap_ioctl(int fd, unsigned long req, ...) {\n    va_list ap; va_start(ap, req);\n    unsigned long arg = va_arg(ap, unsigned long);\n    va_end(ap);\n    struct m_fd *f = m_get(fd);\n    if (!f) return m_fail(EBADF);\n    if (f->kind == K_SYS) {\n        if (req == KVM_GET_API_VERSION) return (unsigned)arg ? m_fail(EINVAL) : m_api;\n        if (req == KVM_CHECK_EXTENSION) return (int)m_cap((unsigned)arg);\n        if (req == KVM_GET_VCPU_MMAP_SIZE) return (unsigned)arg ? m_fail(EINVAL) : (int)(3 * PG);\n        if (req == KVM_CREATE_VM) {\n            if (m_vm_err) return m_fail(m_vm_err);\n            if ((unsigned)arg != 0 || m_nvm >= 4) return m_fail(EINVAL);\n            int nfd = m_alloc(K_VM, m_nvm, 0);\n            if (nfd < 0) return m_fail(EMFILE);\n            m_nvm++;\n            return nfd;\n        }\n    } else if (f->kind == K_VM) {\n        struct m_vm *v = &m_vms[f->vm];\n        if (req == KVM_CHECK_EXTENSION) return (int)m_cap((unsigned)arg);\n        if (req == KVM_CREATE_VCPU) {\n            if (v->nv >= M_MAXV) return m_fail(EINVAL);\n            for (int i = 0; i < v->nv; i++) if (v->ids[i] == (int)(unsigned)arg) return m_fail(EEXIST);\n            int nfd = m_alloc(K_VCPU, f->vm, (int)(unsigned)arg);\n            if (nfd < 0) return m_fail(EMFILE);\n            v->ids[v->nv++] = (int)(unsigned)arg;\n            return nfd;\n        }\n        if (req == KVM_SET_USER_MEMORY_REGION) {\n            if (arg == 0) return m_fail(EFAULT);\n            return m_set_region(f, (struct kvm_userspace_memory_region *)arg);\n        }\n    } else if (f->kind == K_VCPU) {\n        if (req == KVM_RUN) return (unsigned)arg ? m_fail(EINVAL) : m_run(f);\n    }\n    return m_fail(ENOTTY);\n}\nvoid *__wrap_mmap(void *addr, size_t len, int prot, int flags, int fd, off_t off) {\n    struct m_fd *f = (flags & MAP_ANONYMOUS) ? NULL : m_get(fd);\n    if (f && f->kind != K_VCPU) { errno = ENODEV; return MAP_FAILED; }\n    if (f && (off != 0 || len == 0 || len > 3 * PG)) { errno = EINVAL; return MAP_FAILED; }\n    if (!f && (flags & MAP_ANONYMOUS) == 0) return __real_mmap(addr, len, prot, flags, fd, off);\n    void *p = __real_mmap(f ? NULL : addr, f ? 3 * PG : len, f ? PROT_READ | PROT_WRITE : prot,\n                          f ? MAP_SHARED | MAP_ANONYMOUS : flags, f ? -1 : fd, f ? 0 : off);\n    if (p == MAP_FAILED) return p;\n    for (int i = 0; i < 32; i++)\n        if (!m_maps[i].a) { m_maps[i].a = p; m_maps[i].l = len; break; }\n    if (f) { f->run = p; f->runlen = len; }\n    return p;\n}\nint __wrap_munmap(void *addr, size_t len) {\n    int r = __real_munmap(addr, len);\n    if (r == 0)\n        for (int i = 0; i < 32; i++)\n            if (m_maps[i].a == addr) {\n                m_maps[i].a = NULL;\n                for (int k = 0; k < M_FDS; k++) if (m_fds[k].run == addr) m_fds[k].run = NULL;\n                break;\n            }\n    return r;\n}\n\n/* ---- helpers of the driver ---- */\nstatic void m_reset(void) {\n    memset(m_fds, 0, sizeof m_fds); memset(m_vms, 0, sizeof m_vms); memset(m_maps, 0, sizeof m_maps);\n    m_nvm = 0; m_open_err = 0; m_api = 12; m_vm_err = 0; m_runs = 0; m_opens = 0; m_oflags = 0; m_eintr = 0;\n}\nstatic const char *m_en(int e) {\n    switch (e) {\n    case ENOENT: return \"ENOENT\"; case EACCES: return \"EACCES\"; case EINVAL: return \"EINVAL\";\n    case EEXIST: return \"EEXIST\"; case EBADF: return \"EBADF\"; case EINTR: return \"EINTR\";\n    case EMFILE: return \"EMFILE\"; case ENOMEM: return \"ENOMEM\"; case EPROTO: return \"EPROTO\";\n    case E2BIG: return \"E2BIG\"; case EIO: return \"EIO\"; case ENOTTY: return \"ENOTTY\";\n    case EFAULT: return \"EFAULT\"; case ENODEV: return \"ENODEV\"; case EPERM: return \"EPERM\";\n    }\n    return \"E?\";\n}\nstatic void m_pr(const char *label, long r) {\n    if (r < 0 && r > -4096) printf(\"%s: -%s\\n\", label, m_en((int)-r));\n    else printf(\"%s: %ld\\n\", label, r);\n}\n/* print the result of a raw ioctl/mmap-like call that reports errors through errno */\nstatic void m_pre(const char *label, long r) {\n    int e = errno;\n    if (r < 0) printf(\"%s: -%s\\n\", label, m_en(e));\n    else printf(\"%s: %ld\\n\", label, r);\n}\nstatic void m_leaks(void) { printf(\"leaks: fds=%d maps=%d\\n\", m_nopen(), m_nmaps()); }\nstatic const char *m_kind(int fd) {\n    struct m_fd *f = m_get(fd);\n    return !f ? \"none\" : f->kind == K_SYS ? \"system\" : f->kind == K_VM ? \"vm\" : \"vcpu\";\n}\n/* driver-side setup of a VM with the guest program at guest address 0 and one vCPU mapped for KVM_RUN */\nstatic uint8_t *m_boot(const uint8_t *prog, int len, int *vcpu, struct kvm_run **run) {\n    int kvm = open(\"/dev/kvm\", O_RDWR | O_CLOEXEC);\n    int vm = ioctl(kvm, KVM_CREATE_VM, 0);\n    uint8_t *mem = mmap(NULL, PG, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);\n    memcpy(mem, prog, len);\n    struct kvm_userspace_memory_region r = { .slot = 0, .guest_phys_addr = 0, .memory_size = PG, .userspace_addr = (uintptr_t)mem };\n    ioctl(vm, KVM_SET_USER_MEMORY_REGION, &r);\n    *vcpu = ioctl(vm, KVM_CREATE_VCPU, 0);\n    *run = mmap(NULL, 3 * PG, PROT_READ | PROT_WRITE, MAP_SHARED, *vcpu, 0);\n    return mem;\n}\n\n\nstatic void play(const char *label, const uint8_t *prog, int len) {\n    int vcpu; struct kvm_run *run;\n    char out[64];\n    memset(out, ''#'', sizeof out);\n    m_boot(prog, len, &vcpu, &run);\n    long r = run_device(vcpu, run, out, 64);\n    m_pr(label, r);\n    if (r >= 0) printf(\"output: [%s]\\n\", out);\n}\nint main(void) {\n    /* read, +''0'', print; read, +''0'', print */\n    static const uint8_t two_reads[] = { 0x04, 0, 0, 0, 0x10, 0x06, ''0'', 0x05, 0xf8, 0x03,\n                                         0x04, 0, 0, 0, 0x10, 0x06, ''0'', 0x05, 0xf8, 0x03, 0x00 };\n    m_reset(); play(\"two reads\", two_reads, sizeof two_reads);\n    static const uint8_t set_then_read[] = { 0x03, 0, 0, 0, 0x10, 5, 0x04, 0, 0, 0, 0x10, 0x06, ''0'', 0x05, 0xf8, 0x03, 0x00 };\n    m_reset(); play(\"write then read\", set_then_read, sizeof set_then_read);\n    static const uint8_t other[] = { 0x03, 0, 0, 0, 0x20, 7, 0x04, 0, 0, 0, 0x20, 0x06, 0x42, 0x05, 0xf8, 0x03, 0x00 };\n    m_reset(); play(\"other address\", other, sizeof other);\n    static const uint8_t reads3[] = { 0x04, 0, 0, 0, 0x10, 0x04, 0, 0, 0, 0x10, 0x04, 0, 0, 0, 0x10, 0x06, ''0'', 0x05, 0xf8, 0x03, 0x00 };\n    m_reset(); m_eintr = 6; play(\"reads with signals\", reads3, sizeof reads3);\n    printf(\"KVM_RUN calls: %d\\n\", m_runs);\n    static const uint8_t down[] = { 0xFF };\n    m_reset(); play(\"shutdown\", down, sizeof down);\n    return 0;\n}\n", "expected": ["two reads: 2", "output: [01]", "write then read: 1", "output: [5]", "other address: 1", "output: [A]", "reads with signals: 1", "output: [2]", "KVM_RUN calls: 7", "shutdown: -EIO"], "flags": "-std=gnu11 -O1 -Wall -Wl,--wrap=open,--wrap=ioctl,--wrap=close,--wrap=mmap,--wrap=munmap"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 28, 'la28-tiny-guest', 7, 'c', 'Крошечный гость целиком', 'Соберите всё в один VMM без libvirt и QEMU. Напишите int tiny_guest(const uint8_t *prog, size_t len, char *out, size_t cap): 1) откройте /dev/kvm (O_RDWR | O_CLOEXEC) и проверьте, что версия API равна KVM_API_VERSION (иначе -EPROTO); 2) создайте ВМ; 3) выделите mmap одну страницу (4096 байт) гостевой памяти, скопируйте в неё prog и зарегистрируйте её в слоте 0 по гостевому адресу 0 (если len больше страницы, верните -E2BIG, ничего не выделив); 4) создайте vCPU с номером 0; 5) узнайте размер области kvm_run через ioctl(kvm, KVM_GET_VCPU_MMAP_SIZE, 0) и отобразите её mmap-ом дескриптора vCPU (PROT_READ | PROT_WRITE, MAP_SHARED, смещение 0); 6) выполните цикл KVM_RUN: EINTR повторяет вызов; вывод в порт 0x3f8 (байт по адресу (char *)run + run->io.data_offset) добавляйте в out (не больше cap-1 символов); остальной ввод-вывод игнорируйте, ввод отвечайте байтами 0xFF; KVM_EXIT_HLT — успех (нулевой байт в конец out, результат — число символов); любой другой выход — -EIO; 7) на любом пути освободите всё, что открыли и отобразили. Если на каком-то шаге вызов не удался, верните его -errno. Помните: область kvm_run занимает больше одной страницы, берите размер у ядра, а не sizeof(struct kvm_run). Гость в модели не настоящий машинный код, а игрушечная программа (лабораторное упрощение): запись в память гостя, начиная с адреса 0. Команды: 0x00 останов (выход KVM_EXIT_HLT); 0x01 pL pH v вывод байта v в порт pH:pL (KVM_EXIT_IO, direction OUT, size 1, count 1, данные лежат по run + data_offset); 0x02 pL pH ввод из порта (KVM_EXIT_IO, direction IN: ответ положите по тому же data_offset до следующего KVM_RUN); 0x05 pL pH вывод в порт накопителя acc; 0x06 v прибавить v к acc; 0xFF KVM_EXIT_SHUTDOWN; неизвестный код даёт KVM_EXIT_INTERNAL_ERROR. Устройства /dev/kvm в песочнице нет: драйвер подставляет МОДЕЛЬ ядра (лабораторное упрощение, константы и структуры настоящие, из linux/kvm.h; поведение модели описано в условии). Пишите обычный код с open, ioctl, close, mmap, как для настоящего устройства.', '#include <errno.h>
#include <fcntl.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/kvm.h>

int tiny_guest(const uint8_t *prog, size_t len, char *out, size_t cap) {
    // /dev/kvm -> ВМ -> память -> vCPU -> kvm_run -> цикл KVM_RUN -> очистка
    return -1;
}
', 'Удобно написать цепочку шагов с метками для очистки (goto) или вспомогательную функцию run_loop. Отображение kvm_run снимайте munmap, а три дескриптора закрывайте close.', '{"driver": "/*__DRIVER__*/\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <stdint.h>\n#include <stdarg.h>\n#include <errno.h>\n#include <fcntl.h>\n#include <unistd.h>\n#include <sys/mman.h>\n#include <sys/ioctl.h>\n#include <linux/kvm.h>\n\n/* ---- LAB MODEL of /dev/kvm: a fake kernel behind the linker''s --wrap (the sandbox has no /dev/kvm) ---- */\nextern int __real_open(const char *, int, ...);\nextern int __real_close(int);\nextern void *__real_mmap(void *, size_t, int, int, int, off_t);\nextern int __real_munmap(void *, size_t);\n\n#define PG 4096UL\n#define M_FDS 16\n#define M_SLOTS 32\n#define M_MAXV 8\nenum { K_FREE, K_SYS, K_VM, K_VCPU };\nstruct m_slot { int used; uint64_t gpa, size, uaddr; };\nstruct m_vm { struct m_slot s[M_SLOTS]; int nv; int ids[M_MAXV]; };\nstruct m_fd { int kind, vm, id; struct kvm_run *run; size_t runlen; uint64_t pc; uint8_t acc; int pend; };\nstatic struct m_fd m_fds[M_FDS];\nstatic struct m_vm m_vms[4];\nstatic int m_nvm;\nstatic struct { void *a; size_t l; } m_maps[32];\nstatic int m_open_err, m_api = 12, m_vm_err, m_runs, m_opens, m_oflags;\nstatic unsigned m_eintr; /* bit k set: the (k+1)-th KVM_RUN fails with EINTR */\n\nstatic int m_fail(int e) { errno = e; return -1; }\nstatic struct m_fd *m_get(int fd) {\n    int i = fd - 100;\n    return (i < 0 || i >= M_FDS || m_fds[i].kind == K_FREE) ? NULL : &m_fds[i];\n}\nstatic int m_alloc(int kind, int vm, int id) {\n    for (int i = 0; i < M_FDS; i++)\n        if (m_fds[i].kind == K_FREE) {\n            memset(&m_fds[i], 0, sizeof m_fds[i]);\n            m_fds[i].kind = kind; m_fds[i].vm = vm; m_fds[i].id = id;\n            return 100 + i;\n        }\n    return -1;\n}\nstatic int m_nopen(void) { int n = 0; for (int i = 0; i < M_FDS; i++) n += m_fds[i].kind != K_FREE; return n; }\nstatic int m_nmaps(void) { int n = 0; for (int i = 0; i < 32; i++) n += m_maps[i].a != NULL; return n; }\nstatic long m_cap(unsigned long c) {\n    switch (c) {\n    case KVM_CAP_USER_MEMORY: case KVM_CAP_IMMEDIATE_EXIT: case KVM_CAP_MP_STATE:\n    case KVM_CAP_IOEVENTFD: case KVM_CAP_IRQFD: return 1;\n    case KVM_CAP_NR_VCPUS: return 4;\n    case KVM_CAP_MAX_VCPUS: return M_MAXV;\n    case KVM_CAP_NR_MEMSLOTS: return M_SLOTS;\n    default: return 0;\n    }\n}\nstatic int m_gread(struct m_vm *v, uint64_t gpa, uint8_t *out, int n) {\n    for (int k = 0; k < n; k++) {\n        int ok = 0;\n        for (int i = 0; i < M_SLOTS && !ok; i++) {\n            struct m_slot *s = &v->s[i];\n            if (s->used && gpa + k >= s->gpa && gpa + k < s->gpa + s->size) {\n                out[k] = ((uint8_t *)(uintptr_t)s->uaddr)[gpa + k - s->gpa];\n                ok = 1;\n            }\n        }\n        if (!ok) return -1;\n    }\n    return 0;\n}\n/* the toy guest: opcode lengths; this is NOT machine code, it is the lab''s own tiny instruction set */\nstatic int m_oplen(int op) {\n    switch (op) {\n    case 0x00: case 0xFF: return 1;\n    case 0x01: return 4;  /* OUT port,imm8 */\n    case 0x02: return 3;  /* IN port -> acc */\n    case 0x03: return 6;  /* MMIO write addr32,imm8 */\n    case 0x04: return 5;  /* MMIO read addr32 -> acc */\n    case 0x05: return 3;  /* OUT port,acc */\n    case 0x06: return 2;  /* acc += imm8 */\n    default: return 0;\n    }\n}\nstatic int m_run(struct m_fd *f) {\n    struct m_vm *v = &m_vms[f->vm];\n    struct kvm_run *r = f->run;\n    if (!r) return m_fail(EINVAL);\n    uint8_t *pio = (uint8_t *)r + PG;\n    m_runs++;\n    if ((m_runs <= 31 && ((m_eintr >> (m_runs - 1)) & 1)) || r->immediate_exit) {\n        r->exit_reason = KVM_EXIT_INTR;\n        return m_fail(EINTR);\n    }\n    if (f->pend == 1) f->acc = pio[0];\n    if (f->pend == 2) f->acc = r->mmio.data[0];\n    f->pend = 0;\n    for (;;) {\n        uint8_t b[8];\n        int n;\n        if (m_gread(v, f->pc, b, 1)) { r->exit_reason = KVM_EXIT_FAIL_ENTRY; r->fail_entry.hardware_entry_failure_reason = 0x1000; r->fail_entry.cpu = 0; return 0; }\n        n = m_oplen(b[0]);\n        if (n == 0) {\n            r->exit_reason = KVM_EXIT_INTERNAL_ERROR;\n            r->internal.suberror = KVM_INTERNAL_ERROR_EMULATION;\n            r->internal.ndata = 0;\n            return 0;\n        }\n        if (m_gread(v, f->pc, b, n)) { r->exit_reason = KVM_EXIT_FAIL_ENTRY; r->fail_entry.hardware_entry_failure_reason = 0x1000; r->fail_entry.cpu = 0; return 0; }\n        f->pc += n;\n        switch (b[0]) {\n        case 0x00: r->exit_reason = KVM_EXIT_HLT; return 0;\n        case 0xFF: r->exit_reason = KVM_EXIT_SHUTDOWN; return 0;\n        case 0x06: f->acc = (uint8_t)(f->acc + b[1]); break;\n        case 0x01: case 0x05:\n            if (f->runlen < 2 * PG) return m_fail(EFAULT);\n            r->exit_reason = KVM_EXIT_IO;\n            r->io.direction = KVM_EXIT_IO_OUT; r->io.size = 1; r->io.count = 1;\n            r->io.port = (uint16_t)(b[1] | b[2] << 8); r->io.data_offset = PG;\n            pio[0] = b[0] == 0x01 ? b[3] : f->acc;\n            return 0;\n        case 0x02:\n            if (f->runlen < 2 * PG) return m_fail(EFAULT);\n            r->exit_reason = KVM_EXIT_IO;\n            r->io.direction = KVM_EXIT_IO_IN; r->io.size = 1; r->io.count = 1;\n            r->io.port = (uint16_t)(b[1] | b[2] << 8); r->io.data_offset = PG;\n            pio[0] = 0; f->pend = 1;\n            return 0;\n        case 0x03: case 0x04:\n            r->exit_reason = KVM_EXIT_MMIO;\n            r->mmio.phys_addr = (uint32_t)b[1] | (uint32_t)b[2] << 8 | (uint32_t)b[3] << 16 | (uint32_t)b[4] << 24;\n            memset(r->mmio.data, 0, 8);\n            r->mmio.len = 1;\n            if (b[0] == 0x03) { r->mmio.is_write = 1; r->mmio.data[0] = b[5]; }\n            else { r->mmio.is_write = 0; f->pend = 2; }\n            return 0;\n        }\n    }\n}\nstatic int m_set_region(struct m_fd *f, struct kvm_userspace_memory_region *m) {\n    struct m_vm *v = &m_vms[f->vm];\n    unsigned slot = m->slot & 0xffff;\n    if (m->flags & ~(KVM_MEM_LOG_DIRTY_PAGES | KVM_MEM_READONLY)) return m_fail(EINVAL);\n    if ((m->memory_size & (PG - 1)) || (m->guest_phys_addr & (PG - 1)) || (m->userspace_addr & (PG - 1))) return m_fail(EINVAL);\n    if ((m->slot >> 16) != 0 || slot >= M_SLOTS) return m_fail(EINVAL);\n    if (m->guest_phys_addr + m->memory_size < m->guest_phys_addr) return m_fail(EINVAL);\n    struct m_slot *s = &v->s[slot];\n    if (m->memory_size == 0) {\n        if (!s->used) return m_fail(EINVAL);\n        s->used = 0;\n        return 0;\n    }\n    if (s->used && (m->userspace_addr != s->uaddr || m->memory_size != s->size)) return m_fail(EINVAL);\n    for (int i = 0; i < M_SLOTS; i++)\n        if (i != (int)slot && v->s[i].used && m->guest_phys_addr < v->s[i].gpa + v->s[i].size &&\n            v->s[i].gpa < m->guest_phys_addr + m->memory_size)\n            return m_fail(EEXIST);\n    s->used = 1; s->gpa = m->guest_phys_addr; s->size = m->memory_size; s->uaddr = m->userspace_addr;\n    return 0;\n}\nint __wrap_open(const char *path, int flags, ...) {\n    if (strcmp(path, \"/dev/kvm\") == 0) {\n        m_opens++; m_oflags = flags;\n        if (m_open_err) return m_fail(m_open_err);\n        int fd = m_alloc(K_SYS, 0, 0);\n        return fd < 0 ? m_fail(EMFILE) : fd;\n    }\n    va_list ap; va_start(ap, flags);\n    int mode = (flags & O_CREAT) ? va_arg(ap, int) : 0;\n    va_end(ap);\n    return __real_open(path, flags, mode);\n}\nint __wrap_close(int fd) {\n    struct m_fd *f = m_get(fd);\n    if (!f) return __real_close(fd);\n    f->kind = K_FREE;\n    return 0;\n}\nint __wrap_ioctl(int fd, unsigned long req, ...) {\n    va_list ap; va_start(ap, req);\n    unsigned long arg = va_arg(ap, unsigned long);\n    va_end(ap);\n    struct m_fd *f = m_get(fd);\n    if (!f) return m_fail(EBADF);\n    if (f->kind == K_SYS) {\n        if (req == KVM_GET_API_VERSION) return (unsigned)arg ? m_fail(EINVAL) : m_api;\n        if (req == KVM_CHECK_EXTENSION) return (int)m_cap((unsigned)arg);\n        if (req == KVM_GET_VCPU_MMAP_SIZE) return (unsigned)arg ? m_fail(EINVAL) : (int)(3 * PG);\n        if (req == KVM_CREATE_VM) {\n            if (m_vm_err) return m_fail(m_vm_err);\n            if ((unsigned)arg != 0 || m_nvm >= 4) return m_fail(EINVAL);\n            int nfd = m_alloc(K_VM, m_nvm, 0);\n            if (nfd < 0) return m_fail(EMFILE);\n            m_nvm++;\n            return nfd;\n        }\n    } else if (f->kind == K_VM) {\n        struct m_vm *v = &m_vms[f->vm];\n        if (req == KVM_CHECK_EXTENSION) return (int)m_cap((unsigned)arg);\n        if (req == KVM_CREATE_VCPU) {\n            if (v->nv >= M_MAXV) return m_fail(EINVAL);\n            for (int i = 0; i < v->nv; i++) if (v->ids[i] == (int)(unsigned)arg) return m_fail(EEXIST);\n            int nfd = m_alloc(K_VCPU, f->vm, (int)(unsigned)arg);\n            if (nfd < 0) return m_fail(EMFILE);\n            v->ids[v->nv++] = (int)(unsigned)arg;\n            return nfd;\n        }\n        if (req == KVM_SET_USER_MEMORY_REGION) {\n            if (arg == 0) return m_fail(EFAULT);\n            return m_set_region(f, (struct kvm_userspace_memory_region *)arg);\n        }\n    } else if (f->kind == K_VCPU) {\n        if (req == KVM_RUN) return (unsigned)arg ? m_fail(EINVAL) : m_run(f);\n    }\n    return m_fail(ENOTTY);\n}\nvoid *__wrap_mmap(void *addr, size_t len, int prot, int flags, int fd, off_t off) {\n    struct m_fd *f = (flags & MAP_ANONYMOUS) ? NULL : m_get(fd);\n    if (f && f->kind != K_VCPU) { errno = ENODEV; return MAP_FAILED; }\n    if (f && (off != 0 || len == 0 || len > 3 * PG)) { errno = EINVAL; return MAP_FAILED; }\n    if (!f && (flags & MAP_ANONYMOUS) == 0) return __real_mmap(addr, len, prot, flags, fd, off);\n    void *p = __real_mmap(f ? NULL : addr, f ? 3 * PG : len, f ? PROT_READ | PROT_WRITE : prot,\n                          f ? MAP_SHARED | MAP_ANONYMOUS : flags, f ? -1 : fd, f ? 0 : off);\n    if (p == MAP_FAILED) return p;\n    for (int i = 0; i < 32; i++)\n        if (!m_maps[i].a) { m_maps[i].a = p; m_maps[i].l = len; break; }\n    if (f) { f->run = p; f->runlen = len; }\n    return p;\n}\nint __wrap_munmap(void *addr, size_t len) {\n    int r = __real_munmap(addr, len);\n    if (r == 0)\n        for (int i = 0; i < 32; i++)\n            if (m_maps[i].a == addr) {\n                m_maps[i].a = NULL;\n                for (int k = 0; k < M_FDS; k++) if (m_fds[k].run == addr) m_fds[k].run = NULL;\n                break;\n            }\n    return r;\n}\n\n/* ---- helpers of the driver ---- */\nstatic void m_reset(void) {\n    memset(m_fds, 0, sizeof m_fds); memset(m_vms, 0, sizeof m_vms); memset(m_maps, 0, sizeof m_maps);\n    m_nvm = 0; m_open_err = 0; m_api = 12; m_vm_err = 0; m_runs = 0; m_opens = 0; m_oflags = 0; m_eintr = 0;\n}\nstatic const char *m_en(int e) {\n    switch (e) {\n    case ENOENT: return \"ENOENT\"; case EACCES: return \"EACCES\"; case EINVAL: return \"EINVAL\";\n    case EEXIST: return \"EEXIST\"; case EBADF: return \"EBADF\"; case EINTR: return \"EINTR\";\n    case EMFILE: return \"EMFILE\"; case ENOMEM: return \"ENOMEM\"; case EPROTO: return \"EPROTO\";\n    case E2BIG: return \"E2BIG\"; case EIO: return \"EIO\"; case ENOTTY: return \"ENOTTY\";\n    case EFAULT: return \"EFAULT\"; case ENODEV: return \"ENODEV\"; case EPERM: return \"EPERM\";\n    }\n    return \"E?\";\n}\nstatic void m_pr(const char *label, long r) {\n    if (r < 0 && r > -4096) printf(\"%s: -%s\\n\", label, m_en((int)-r));\n    else printf(\"%s: %ld\\n\", label, r);\n}\n/* print the result of a raw ioctl/mmap-like call that reports errors through errno */\nstatic void m_pre(const char *label, long r) {\n    int e = errno;\n    if (r < 0) printf(\"%s: -%s\\n\", label, m_en(e));\n    else printf(\"%s: %ld\\n\", label, r);\n}\nstatic void m_leaks(void) { printf(\"leaks: fds=%d maps=%d\\n\", m_nopen(), m_nmaps()); }\nstatic const char *m_kind(int fd) {\n    struct m_fd *f = m_get(fd);\n    return !f ? \"none\" : f->kind == K_SYS ? \"system\" : f->kind == K_VM ? \"vm\" : \"vcpu\";\n}\n/* driver-side setup of a VM with the guest program at guest address 0 and one vCPU mapped for KVM_RUN */\nstatic uint8_t *m_boot(const uint8_t *prog, int len, int *vcpu, struct kvm_run **run) {\n    int kvm = open(\"/dev/kvm\", O_RDWR | O_CLOEXEC);\n    int vm = ioctl(kvm, KVM_CREATE_VM, 0);\n    uint8_t *mem = mmap(NULL, PG, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);\n    memcpy(mem, prog, len);\n    struct kvm_userspace_memory_region r = { .slot = 0, .guest_phys_addr = 0, .memory_size = PG, .userspace_addr = (uintptr_t)mem };\n    ioctl(vm, KVM_SET_USER_MEMORY_REGION, &r);\n    *vcpu = ioctl(vm, KVM_CREATE_VCPU, 0);\n    *run = mmap(NULL, 3 * PG, PROT_READ | PROT_WRITE, MAP_SHARED, *vcpu, 0);\n    return mem;\n}\n\n\nstatic const uint8_t HI[] = { 0x01, 0xf8, 0x03, ''H'', 0x01, 0xf8, 0x03, ''i'', 0x01, 0xf8, 0x03, ''!'', 0x00 };\n\nstatic void play(const char *label, const uint8_t *prog, size_t len) {\n    char out[64];\n    memset(out, ''#'', sizeof out);\n    long r = tiny_guest(prog, len, out, 64);\n    m_pr(label, r);\n    if (r >= 0) printf(\"output: [%s]\\n\", out);\n    m_leaks();\n}\nint main(void) {\n    m_reset(); play(\"hello\", HI, sizeof HI);\n    m_reset(); m_eintr = 3; play(\"hello with signals\", HI, sizeof HI);\n    m_reset(); m_open_err = ENOENT; play(\"module not loaded\", HI, sizeof HI);\n    m_reset(); m_open_err = EACCES; play(\"no permission\", HI, sizeof HI);\n    m_reset(); m_api = 11; play(\"old API\", HI, sizeof HI);\n    m_reset(); m_vm_err = ENOMEM; play(\"create vm fails\", HI, sizeof HI);\n    static uint8_t big[5000];\n    m_reset(); play(\"program too big\", big, sizeof big);\n    static uint8_t full[4096];\n    for (int i = 0; i < 4096; i += 2) { full[i] = 0x06; full[i + 1] = 1; }\n    m_reset(); play(\"runs off the end\", full, sizeof full);\n    static const uint8_t down[] = { 0x01, 0xf8, 0x03, ''a'', 0xFF };\n    m_reset(); play(\"shutdown\", down, sizeof down);\n    static const uint8_t in[] = { 0x02, 0x60, 0x00, 0x06, 0x42, 0x05, 0xf8, 0x03, 0x00 };\n    m_reset(); play(\"port input\", in, sizeof in);\n    return 0;\n}\n", "expected": ["hello: 3", "output: [Hi!]", "leaks: fds=0 maps=0", "hello with signals: 3", "output: [Hi!]", "leaks: fds=0 maps=0", "module not loaded: -ENOENT", "leaks: fds=0 maps=0", "no permission: -EACCES", "leaks: fds=0 maps=0", "old API: -EPROTO", "leaks: fds=0 maps=0", "create vm fails: -ENOMEM", "leaks: fds=0 maps=0", "program too big: -E2BIG", "leaks: fds=0 maps=0", "runs off the end: -EIO", "leaks: fds=0 maps=0", "shutdown: -EIO", "leaks: fds=0 maps=0", "port input: 1", "output: [A]", "leaks: fds=0 maps=0"], "flags": "-std=gnu11 -O1 -Wall -Wl,--wrap=open,--wrap=ioctl,--wrap=close,--wrap=mmap,--wrap=munmap"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 28, 'la28-dev-access', 8, 'func', 'Кто может открыть /dev/kvm', 'open("/dev/kvm", O_RDWR) может не удаться по двум причинам: файла нет (модуль kvm не загружен или у процессора нет расширений виртуализации; ошибка ENOENT) или нет прав (EACCES). Напишите функцию kvm_access(ls_line, user, groups): ls_line — строка вывода ls -l /dev/kvm (или пустая строка, если файла нет), user — имя пользователя, groups — список имён его групп (включая основную). Верните "ENOENT", если файла нет; иначе "ok" или "EACCES". Для открытия на чтение и запись нужны оба бита r и w. Берите тот набор прав, который применяется к пользователю: сначала владелец (если имя совпадает с владельцем), иначе группа (если группа файла есть в groups), иначе остальные. Пользователь root проходит всегда. Строка прав может быть длиннее десяти символов: в конце бывает + (ACL) или . (контекст SELinux), их надо игнорировать. Списки ACL здесь не разбираются.', 'def kvm_access(ls_line, user, groups):
    pass
', 'split() даёт поля: [0] права, [2] владелец, [3] группа. Права — первые 10 символов; символы 1-3 владелец, 4-6 группа, 7-9 остальные.', '{"func": "kvm_access", "tests": [{"args": ["crw-rw---- 1 root kvm 10, 232 Nov  3 10:00 /dev/kvm", "alice", ["alice", "kvm"]], "expected": "ok"}, {"args": ["crw-rw---- 1 root kvm 10, 232 Nov  3 10:00 /dev/kvm", "bob", ["bob", "users"]], "expected": "EACCES"}, {"args": ["crw-rw-rw- 1 root kvm 10, 232 Nov  3 10:00 /dev/kvm", "bob", ["bob"]], "expected": "ok"}, {"args": ["crw-rw----+ 1 root kvm 10, 232 Nov  3 10:00 /dev/kvm", "carol", ["carol", "kvm", "wheel"]], "expected": "ok"}, {"args": ["crw-rw----. 1 root kvm 10, 232 Nov  3 10:00 /dev/kvm", "dave", ["dave"]], "expected": "EACCES"}, {"args": ["crw------- 1 root kvm 10, 232 Nov  3 10:00 /dev/kvm", "erin", ["erin", "kvm"]], "expected": "EACCES"}, {"args": ["crw------- 1 erin kvm 10, 232 Nov  3 10:00 /dev/kvm", "erin", ["erin", "kvm"]], "expected": "ok"}, {"args": ["cr--r--r-- 1 root kvm 10, 232 Nov  3 10:00 /dev/kvm", "frank", ["frank"]], "expected": "EACCES"}, {"args": ["crw-r----- 1 root kvm 10, 232 Nov  3 10:00 /dev/kvm", "gina", ["gina", "kvm"]], "expected": "EACCES"}, {"args": ["crw------- 1 root root 10, 232 Nov  3 10:00 /dev/kvm", "root", ["root"]], "expected": "ok"}, {"args": ["", "alice", ["alice", "kvm"]], "expected": "ENOENT"}, {"args": ["crw-rw---- 1 root kvm 10, 232 Nov  3 10:00 /dev/kvm", "hank", ["kvm"]], "expected": "ok"}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 28, 'la28-fd-levels', 9, 'func', 'Три уровня дескрипторов по strace', 'strace показывает, как VMM разговаривает с KVM: strace умеет печатать имена ioctl из linux/kvm.h. Дескриптор из open("/dev/kvm") — системный, из KVM_CREATE_VM — дескриптор ВМ, из KVM_CREATE_VCPU — vCPU. Напишите функцию fd_levels(lines): lines — строки strace (например, openat(AT_FDCWD, "/dev/kvm", O_RDWR|O_CLOEXEC) = 3, ioctl(3, KVM_CREATE_VM, 0) = 4, close(4) = 0). Верните список кортежей (номер дескриптора, "system" | "vm" | "vcpu"), отсортированный по номеру, для дескрипторов, открытых на момент конца журнала. Правила: вызовы с отрицательным результатом (= -1 ENOMEM (...)) ничего не создают; open/openat считаются, только если путь "/dev/kvm"; KVM_CREATE_VM создаёт ВМ, только если вызван на системном дескрипторе; KVM_CREATE_VCPU создаёт vCPU, только если вызван на дескрипторе ВМ; close(N) удаляет дескриптор (номер потом может быть использован снова); остальные строки пропускайте. Если strace запущен с -f, строки могут начинаться с [pid  411] — такой префикс надо отбросить (таблица дескрипторов общая).', 'def fd_levels(lines):
    pass
', 'Регулярное выражение вида name(args) = число. Для ioctl первый аргумент — номер дескриптора, второй — имя запроса.', '{"func": "fd_levels", "tests": [{"args": [["openat(AT_FDCWD, \"/dev/kvm\", O_RDWR|O_CLOEXEC) = 3", "ioctl(3, KVM_GET_API_VERSION, 0) = 12", "ioctl(3, KVM_CREATE_VM, 0) = 4", "ioctl(4, KVM_CREATE_VCPU, 0) = 5"]], "expected": [{"__tuple__": [3, "system"]}, {"__tuple__": [4, "vm"]}, {"__tuple__": [5, "vcpu"]}]}, {"args": [["openat(AT_FDCWD, \"/dev/kvm\", O_RDWR|O_CLOEXEC) = -1 ENOENT (No such file or directory)"]], "expected": []}, {"args": [["openat(AT_FDCWD, \"/dev/kvm\", O_RDWR|O_CLOEXEC) = 3", "ioctl(3, KVM_CREATE_VM, 0) = 4", "ioctl(4, KVM_CREATE_VCPU, 0) = 5", "ioctl(4, KVM_CREATE_VCPU, 1) = 6", "close(5) = 0"]], "expected": [{"__tuple__": [3, "system"]}, {"__tuple__": [4, "vm"]}, {"__tuple__": [6, "vcpu"]}]}, {"args": [["openat(AT_FDCWD, \"/dev/kvm\", O_RDWR|O_CLOEXEC) = 3", "ioctl(3, KVM_CREATE_VM, 0) = -1 ENOMEM (Cannot allocate memory)", "ioctl(3, KVM_CREATE_VCPU, 0) = -1 ENOTTY (Inappropriate ioctl for device)"]], "expected": [{"__tuple__": [3, "system"]}]}, {"args": [["[pid  411] openat(AT_FDCWD, \"/dev/kvm\", O_RDWR|O_CLOEXEC) = 7", "[pid  411] ioctl(7, KVM_CREATE_VM, 0) = 8", "[pid  412] ioctl(8, KVM_CREATE_VCPU, 0) = 9", "[pid  412] ioctl(9, KVM_RUN, 0) = 0"]], "expected": [{"__tuple__": [7, "system"]}, {"__tuple__": [8, "vm"]}, {"__tuple__": [9, "vcpu"]}]}, {"args": [["openat(AT_FDCWD, \"/etc/passwd\", O_RDONLY|O_CLOEXEC) = 3", "ioctl(3, KVM_CREATE_VM, 0) = 4"]], "expected": []}, {"args": [["openat(AT_FDCWD, \"/dev/kvm\", O_RDWR) = 3", "close(3) = 0", "openat(AT_FDCWD, \"/dev/kvm\", O_RDWR) = 3", "ioctl(3, KVM_CREATE_VM, 0) = 4", "close(4) = 0", "ioctl(3, KVM_CREATE_VM, 0) = 4"]], "expected": [{"__tuple__": [3, "system"]}, {"__tuple__": [4, "vm"]}]}, {"args": [[]], "expected": []}]}');
